  const handlePanic = () => {
    stopAudio(); 
    stopArpAndRecording();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setRecordingArpId(null);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleClearActiveChords = () => {
      setActiveChordIds([]);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedData = diamondRef.current.getLatchedNodes();
          if (latchedData.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const uniqueTimestamp = Date.now();
              const soundConfigs: Partial<Record<import('./types').PlayMode, SynthPreset>> = {};
              const usedModes = new Set<import('./types').PlayMode>();

              const simplifiedNodes = latchedData.map(({ node, mode }) => {
                  let modeStr: import('./types').PlayMode = 'normal';
                  if (mode === 1) modeStr = 'latch';
                  else if (mode === 2) modeStr = 'normal';
                  else if (mode === 3) modeStr = 'strum';
                  else if (mode === 4) modeStr = 'brass'; 
                  else if (mode === 5) modeStr = 'keys';
                  else if (mode === 6) modeStr = 'percussion';
                  usedModes.add(modeStr);

                  return { id: node.id, n: node.n, d: node.d, voiceMode: modeStr };
              });

              usedModes.forEach(m => {
                  soundConfigs[m] = JSON.parse(JSON.stringify(presets[m]));
                  if (soundConfigs[m]) {
                      soundConfigs[m]!.id = `chord-${newChords[slotIndex].id}-${m}-${uniqueTimestamp}`;
                  }
              });

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfigs: soundConfigs,
                  soundConfig: undefined 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      if (settings.isSustainEnabled) {
          setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
      } else {
          setActiveChordIds(prev => prev.includes(id) ? [] : [id]);
      }
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined, soundConfigs: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleUiSizeUpdate = (key: keyof AppSettings['uiSizes'], size: UISize) => {
      updateSettings(prev => ({ ...prev, uiSizes: { ...prev.uiSizes, [key]: size } }));
  };

  useKeyboardControls({
      settings, latchMode,
      isSettingsOpen, setIsSettingsOpen,
      isSynthOpen, setIsSynthOpen,
      setMasterVolume, setSpatialScale, setIsSequencerOpen,
      handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
      handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
      handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
      handlePlayAll, handleStopAll
  });

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const top = parseInt(computed.paddingTop) || 0;
      document.body.removeChild(div);
      return { top, left: 0, right: 0, bottom: 0 };
  };
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;
  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
        onClearActiveChords={handleClearActiveChords}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        onVoice={handleVoiceSelect}
        onKeys={handleKeysSelect}
        onPercussion={handlePercussionSelect}
        latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onModulationToggle={handleModulationToggle} isModulationModeActive={settings.isModulationModeActive}
        modulationPathLength={settings.modulationPath.length}
        onModulationUndo={handleModulationUndo}
        onModulationReset={handleModulationReset}
        onShiftToggle={handleShiftToggle} isShiftModeActive={settings.isShiftModeActive}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        uiSizes={settings.uiSizes} updateSize={handleUiSizeUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        presets={presets}
        onPresetChange={setPreset}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />

      <RecordingControls />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; // New flag for conditional unlatching
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Track transferred voices to avoid re-triggering envelopes on React state update
  const transferredVoicesRef = useRef<Set<string>>(new Set());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Sync Shifting IDs ref
  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; }, [shiftingNodeIds]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Shift Ghosts
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Map<string, LatticeNode>();
      if (!settings.isShiftModeActive) return ghosts;

      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode) {
              const transpositionRatio = targetNode.ratio / anchorNode.ratio;
              const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

              shiftingNodeIds.forEach((sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
                      const newCoords: number[] = [];
                      for(let i=0; i<maxLength; i++) {
                          const val = (sourceNode.coords[i] || 0) + (diffCoords[i] || 0);
                          newCoords.push(val);
                      }

                      // Calculate Correct Octave via Pitch Ratio
                      // Reconstruct at Octave 0 to get normalized base
                      const tempId = `${newCoords.join(',')}:0`;
                      const tempNode = reconstructNode(tempId, settings);

                      if (tempNode) {
                          const normalizedBaseRatio = tempNode.ratio;
                          const idealRatio = sourceNode.ratio * transpositionRatio;
                          // Find necessary octave shift to match pitch
                          const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));

                          const newId = `${newCoords.join(',')}:${neededOctave}`;

                          const existing = nodeMap.get(newId);
                          if (existing) {
                              ghosts.set(newId, existing);
                          } else {
                              const ghost = reconstructNode(newId, settings);
                              if (ghost) ghosts.set(newId, ghost);
                          }
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, shiftingNodeIds, nodeMap, phantomNodes, settings]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); 
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   // Check if this ID was manually transferred (shifted) to prevent re-strike
                   if (transferredVoicesRef.current.has(voiceId)) {
                       transferredVoicesRef.current.delete(voiceId);
                       // Do nothing, the voice is already active and running
                   } else {
                       const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                       if (node) {
                           audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                           if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                       }
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper to extract full latch map including active chords
  const getAllLatchesAsMap = () => {
      const map = new Map<string, Map<number, number>>();
      audioLatchedNodesRef.current.forEach((activations, nodeId) => {
          const modeMap = new Map<number, number>();
          activations.forEach(a => {
              if (typeof a.mode === 'number') {
                  modeMap.set(a.mode, a.timestamp);
              }
          });
          if (modeMap.size > 0) map.set(nodeId, modeMap);
      });
      return map;
  };

  // Fuzzy Hit Search for Shift Snap
  const getClosestNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const maxDist = spacing * 0.6; // Generous snap radius
      const maxDistSq = maxDist * maxDist;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      let closest: LatticeNode | null = null;
      let closestDistSq = Infinity;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx;
                  const dy = y - ny;
                  const dSq = dx*dx + dy*dy;
                  if (dSq < closestDistSq && dSq < maxDistSq) {
                      closestDistSq = dSq;
                      closest = node;
                  }
              }
          }
      }

      // Check Phantom Nodes (Active nodes not currently in lattice)
      phantomNodesRef.current.forEach(node => {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          const dSq = dx*dx + dy*dy;
          if (dSq < closestDistSq && dSq < maxDistSq) {
              closestDistSq = dSq;
              closest = node;
          }
      });

      return closest;
  };

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }

      // Check Phantom Nodes
      for (const node of phantomNodesRef.current.values()) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;

          const isLatched = latchedMap.has(node.id);
          const activeZoom = isLatched ? zoomScale : 1.0;
          const activeRadius = baseRadius * activeZoom;

          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
      }

      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  // Helper to execute Shift
  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        if (settings.isModulationModeActive) {
            const newOrigin: GenerationOrigin = {
                coords: hitNode.coords,
                octave: hitNode.octave
            };

            const newPath = [...settings.modulationPath, newOrigin];

            const currentOrigin = settings.modulationPath[settings.modulationPath.length - 1];
            const isSame = currentOrigin.coords.every((v, i) => v === hitNode.coords[i]) && currentOrigin.octave === hitNode.octave;

            if (!isSame) {
                updateSettings({ 
                    modulationPath: newPath,
                    isModulationModeActive: false
                });
            }
            return; 
        }

        // --- SHIFT LOGIC (Initiate / Instant Shift) ---
        const isShiftMode = settings.isShiftModeActive;
        const allLatches = getAllLatchesAsMap(); // Get both manual latches and active chords
        const isClickedLatched = allLatches.has(hitNode.id);

        if (isShiftMode) {
             let anchorNode = null;
             let effectiveShiftingGroup = new Set<string>();

             if (isClickedLatched) {
                 // Existing Logic: Dragging an existing anchor
                 anchorNode = hitNode;
                 effectiveShiftingGroup = new Set(allLatches.keys()); // Shift everything active
             } else {
                 // New Logic: Instant Shift to Clicked Node
                 // 1. Find Implicit Anchor (Closest to "center" or simple ratio)
                 const latchedIds = Array.from(allLatches.keys());
                 if (latchedIds.length > 0) {
                     const nodes = latchedIds.map(id => nodeMapRef.current.get(id) || phantomNodesRef.current.get(id)).filter(n => n) as LatticeNode[];
                     // Sort by complexity/distance from origin to find "root"
                     nodes.sort((a, b) => {
                         const distA = a.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(a.octave);
                         const distB = b.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(b.octave);
                         return distA - distB;
                     });
                     const implicitAnchor = nodes[0];

                     if (implicitAnchor) {
                         // 2. Perform Instant Shift
                         const newLatches = executeShift(implicitAnchor, hitNode, allLatches); 
                         if (newLatches) {
                             // Update State
                             setPersistentLatches(newLatches);
                             persistentLatchesRef.current = newLatches; // Sync ref for immediate interaction consistency

                             // Clear any active stored chord definitions since we've manually moved them
                             if (onClearActiveChords) onClearActiveChords();

                             // The clicked node is now the anchor of the new shape
                             anchorNode = hitNode; 
                             effectiveShiftingGroup = new Set(newLatches.keys());
                         }
                     }
                 }
             }

             if (anchorNode) {
                 setShiftingNodeIds(effectiveShiftingGroup);
                 shiftingNodeIdsRef.current = effectiveShiftingGroup;

                 const newCursor: ActiveCursor = {
                    pointerId: e.pointerId,
                    originNodeId: anchorNode.id, 
                    hoverNodeId: anchorNode.id,
                    hasMoved: false,
                    interactionLockedNodeId: null,
                    isShiftAnchor: true // Mark as anchor for potential dragging
                };

                const nextRef = new Map(activeCursorsRef.current);
                nextRef.set(e.pointerId, newCursor);
                activeCursorsRef.current = nextRef;

                setActiveCursors(prev => {
                    const next = new Map(prev);
                    next.set(e.pointerId, newCursor);
                    return next;
                });
                return;
             }
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        let pendingUnlatch = false;

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             const nodeModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = nodeModes && nodeModes.has(latchMode);

             // Conditional Unlatch: If bend is enabled and note is active, wait for potential drag
             if (isBendEnabled && isAlreadyLatched) {
                 pendingUnlatch = true;
             } else {
                 setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                     const next = new Map(prev);
                     const nModes = next.get(hitNode.id) || new Map<number, number>();

                     if (nModes.has(latchMode)) {
                         nModes.delete(latchMode);
                     } else {
                         nModes.set(latchMode, Date.now());
                     }

                     if (nModes.size > 0) next.set(hitNode.id, nModes);
                     else next.delete(hitNode.id);
                     return next;
                 });
             }
        }

        if (((isBendEnabled || !isSustainActive) && !isShiftMode) && !pendingUnlatch) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        } else if (pendingUnlatch) {
             // Register cursor for bend tracking but don't start new voice
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ONLY voices in the Shifting Group
             const shiftingGroup = shiftingNodeIdsRef.current;
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 if (!shiftingGroup.has(nodeId)) return; // Skip non-shifting nodes

                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             // Glide Cursor Voice (if active)
             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);

             // Glide Sustained/Latched Voice (if interacting with active node)
             if (cursor.pendingUnlatch || persistentLatchesRef.current.has(cursor.originNodeId!)) {
                 const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                 if (latchedModes) {
                     latchedModes.forEach((_, mode) => {
                         const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                         audioEngine.glideVoice(latchedVoiceId, finalRatio, settingsRef.current.baseFrequency);
                     });
                 }
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         // Auto-Latch Logic
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);

            // Fuzzy target finding for snapping
            let targetNode = getClosestNode(e.clientX, e.clientY);
            // Fallback to strict hoverNodeId if getClosestNode failed but hoverNodeId was somehow valid (rare, but good safety)
            if (!targetNode && cursor.hoverNodeId) {
                 targetNode = nodeMapRef.current.get(cursor.hoverNodeId) || phantomNodesRef.current.get(cursor.hoverNodeId) || null;
            }

            const shiftingGroup = shiftingNodeIdsRef.current;

            if (anchorNode && targetNode) {
                // If dragging to same node, do nothing (Tap-Shift already handled on Down)
                if (anchorNode.id !== targetNode.id) {
                    const allLatches = getAllLatchesAsMap();
                    const newLatches = executeShift(anchorNode, targetNode, allLatches);
                    if (newLatches) {
                        setPersistentLatches(newLatches);
                        if (onClearActiveChords) onClearActiveChords();
                    }
                }
            } else if (!targetNode) {
                // DROP TO DELETE (Stop Sound)
                const newLatches = new Map<string, Map<number, number>>(persistentLatchesRef.current);
                shiftingGroup.forEach(sourceId => {
                    newLatches.delete(sourceId);
                });
                setPersistentLatches(newLatches);
            }

            // Cleanup Shift State
            setShiftingNodeIds(new Set());
            shiftingNodeIdsRef.current = new Set();
        } 
        // --- NORMAL LOGIC ---
        else {
            // Pending Unlatch Logic: If user intended to unlatch but didn't drag/bend, do it now.
            if (cursor.pendingUnlatch && cursor.originNodeId) {
                if (cursor.hoverNodeId === cursor.originNodeId) {
                    // Stayed inside node -> Unlatch (Stop)
                    setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nModes = next.get(cursor.originNodeId!) || new Map<number, number>();
                         nModes.delete(latchMode);
                         if (nModes.size > 0) next.set(cursor.originNodeId!, nModes);
                         else next.delete(cursor.originNodeId!);
                         return next;
                     });
                } else {
                    // Dragged outside (Bent) -> Keep latched, reset pitch
                    // NOTE: The voice stays active in persistentLatches, but we snap pitch back to base.
                    const node = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
                    if (node) {
                        const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                        if (latchedModes) {
                             latchedModes.forEach((_, mode) => {
                                 const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                                 audioEngine.glideVoice(latchedVoiceId, node.ratio, settingsRef.current.baseFrequency);
                             });
                        }
                    }
                }
            }
            else if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

                // SUSTAIN-ON-RELEASE LOGIC (Standard, not already latched)
                if (isSustainActive && cursor.hoverNodeId) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(cursor.hoverNodeId!) || new Map<number, number>();
                         // Add the current instrument mode to the destination node
                         nodeModes.set(latchMode === 0 ? 2 : latchMode, Date.now());
                         next.set(cursor.hoverNodeId!, nodeModes);
                         return next;
                     });
                }

                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current,
              shiftGhostNodes: shiftGhostNodesRef.current // Pass map of ghosts
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; // New flag for conditional unlatching
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Track transferred voices to avoid re-triggering envelopes on React state update
  const transferredVoicesRef = useRef<Set<string>>(new Set());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Sync Shifting IDs ref
  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; }, [shiftingNodeIds]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Shift Ghosts
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Map<string, LatticeNode>();
      if (!settings.isShiftModeActive) return ghosts;

      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode) {
              const transpositionRatio = targetNode.ratio / anchorNode.ratio;
              const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

              shiftingNodeIds.forEach((sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
                      const newCoords: number[] = [];
                      for(let i=0; i<maxLength; i++) {
                          const val = (sourceNode.coords[i] || 0) + (diffCoords[i] || 0);
                          newCoords.push(val);
                      }

                      // Calculate Correct Octave via Pitch Ratio
                      // Reconstruct at Octave 0 to get normalized base
                      const tempId = `${newCoords.join(',')}:0`;
                      const tempNode = reconstructNode(tempId, settings);

                      if (tempNode) {
                          const normalizedBaseRatio = tempNode.ratio;
                          const idealRatio = sourceNode.ratio * transpositionRatio;
                          // Find necessary octave shift to match pitch
                          const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));

                          const newId = `${newCoords.join(',')}:${neededOctave}`;

                          const existing = nodeMap.get(newId);
                          if (existing) {
                              ghosts.set(newId, existing);
                          } else {
                              const ghost = reconstructNode(newId, settings);
                              if (ghost) ghosts.set(newId, ghost);
                          }
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, shiftingNodeIds, nodeMap, phantomNodes, settings]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); 
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   // Check if this ID was manually transferred (shifted) to prevent re-strike
                   if (transferredVoicesRef.current.has(voiceId)) {
                       transferredVoicesRef.current.delete(voiceId);
                       // Do nothing, the voice is already active and running
                   } else {
                       const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                       if (node) {
                           audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                           if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                       }
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper to extract full latch map including active chords
  const getAllLatchesAsMap = () => {
      const map = new Map<string, Map<number, number>>();
      audioLatchedNodesRef.current.forEach((activations, nodeId) => {
          const modeMap = new Map<number, number>();
          activations.forEach(a => {
              if (typeof a.mode === 'number') {
                  modeMap.set(a.mode, a.timestamp);
              }
          });
          if (modeMap.size > 0) map.set(nodeId, modeMap);
      });
      return map;
  };

  // Fuzzy Hit Search for Shift Snap
  const getClosestNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const maxDist = spacing * 0.6; // Generous snap radius
      const maxDistSq = maxDist * maxDist;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      let closest: LatticeNode | null = null;
      let closestDistSq = Infinity;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx;
                  const dy = y - ny;
                  const dSq = dx*dx + dy*dy;
                  if (dSq < closestDistSq && dSq < maxDistSq) {
                      closestDistSq = dSq;
                      closest = node;
                  }
              }
          }
      }

      // Check Phantom Nodes (Active nodes not currently in lattice)
      phantomNodesRef.current.forEach(node => {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          const dSq = dx*dx + dy*dy;
          if (dSq < closestDistSq && dSq < maxDistSq) {
              closestDistSq = dSq;
              closest = node;
          }
      });

      return closest;
  };

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }

      // Check Phantom Nodes
      for (const node of phantomNodesRef.current.values()) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;

          const isLatched = latchedMap.has(node.id);
          const activeZoom = isLatched ? zoomScale : 1.0;
          const activeRadius = baseRadius * activeZoom;

          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
      }

      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  // Helper to execute Shift
  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        if (settings.isModulationModeActive) {
            const newOrigin: GenerationOrigin = {
                coords: hitNode.coords,
                octave: hitNode.octave
            };

            const newPath = [...settings.modulationPath, newOrigin];

            const currentOrigin = settings.modulationPath[settings.modulationPath.length - 1];
            const isSame = currentOrigin.coords.every((v, i) => v === hitNode.coords[i]) && currentOrigin.octave === hitNode.octave;

            if (!isSame) {
                updateSettings({ 
                    modulationPath: newPath,
                    isModulationModeActive: false
                });
            }
            return; 
        }

        // --- SHIFT LOGIC (Initiate / Instant Shift) ---
        const isShiftMode = settings.isShiftModeActive;
        const allLatches = getAllLatchesAsMap(); // Get both manual latches and active chords
        const isClickedLatched = allLatches.has(hitNode.id);

        if (isShiftMode) {
             let anchorNode = null;
             let effectiveShiftingGroup = new Set<string>();

             if (isClickedLatched) {
                 // Existing Logic: Dragging an existing anchor
                 anchorNode = hitNode;
                 effectiveShiftingGroup = new Set(allLatches.keys()); // Shift everything active
             } else {
                 // New Logic: Instant Shift to Clicked Node
                 // 1. Find Implicit Anchor (Closest to "center" or simple ratio)
                 const latchedIds = Array.from(allLatches.keys());
                 if (latchedIds.length > 0) {
                     const nodes = latchedIds.map(id => nodeMapRef.current.get(id) || phantomNodesRef.current.get(id)).filter(n => n) as LatticeNode[];
                     // Sort by complexity/distance from origin to find "root"
                     nodes.sort((a, b) => {
                         const distA = a.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(a.octave);
                         const distB = b.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(b.octave);
                         return distA - distB;
                     });
                     const implicitAnchor = nodes[0];

                     if (implicitAnchor) {
                         // 2. Perform Instant Shift
                         const newLatches = executeShift(implicitAnchor, hitNode, allLatches); 
                         if (newLatches) {
                             // Update State
                             setPersistentLatches(newLatches);
                             persistentLatchesRef.current = newLatches; // Sync ref for immediate interaction consistency

                             // Clear any active stored chord definitions since we've manually moved them
                             if (onClearActiveChords) onClearActiveChords();

                             // The clicked node is now the anchor of the new shape
                             anchorNode = hitNode; 
                             effectiveShiftingGroup = new Set(newLatches.keys());
                         }
                     }
                 }
             }

             if (anchorNode) {
                 setShiftingNodeIds(effectiveShiftingGroup);
                 shiftingNodeIdsRef.current = effectiveShiftingGroup;

                 const newCursor: ActiveCursor = {
                    pointerId: e.pointerId,
                    originNodeId: anchorNode.id, 
                    hoverNodeId: anchorNode.id,
                    hasMoved: false,
                    interactionLockedNodeId: null,
                    isShiftAnchor: true // Mark as anchor for potential dragging
                };

                const nextRef = new Map(activeCursorsRef.current);
                nextRef.set(e.pointerId, newCursor);
                activeCursorsRef.current = nextRef;

                setActiveCursors(prev => {
                    const next = new Map(prev);
                    next.set(e.pointerId, newCursor);
                    return next;
                });
                return;
             }
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        let pendingUnlatch = false;

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             const nodeModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = nodeModes && nodeModes.has(latchMode);

             // Conditional Unlatch: If bend is enabled and note is active, wait for potential drag
             if (isBendEnabled && isAlreadyLatched) {
                 pendingUnlatch = true;
             } else {
                 setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                     const next = new Map(prev);
                     const nModes = next.get(hitNode.id) || new Map<number, number>();

                     if (nModes.has(latchMode)) {
                         nModes.delete(latchMode);
                     } else {
                         nModes.set(latchMode, Date.now());
                     }

                     if (nModes.size > 0) next.set(hitNode.id, nModes);
                     else next.delete(hitNode.id);
                     return next;
                 });
             }
        }

        if (((isBendEnabled || !isSustainActive) && !isShiftMode) && !pendingUnlatch) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        } else if (pendingUnlatch) {
             // Register cursor for bend tracking but don't start new voice
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ONLY voices in the Shifting Group
             const shiftingGroup = shiftingNodeIdsRef.current;
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 if (!shiftingGroup.has(nodeId)) return; // Skip non-shifting nodes

                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             // Glide Cursor Voice (if active)
             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);

             // Glide Sustained/Latched Voice (if interacting with active node)
             if (cursor.pendingUnlatch || persistentLatchesRef.current.has(cursor.originNodeId!)) {
                 const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                 if (latchedModes) {
                     latchedModes.forEach((_, mode) => {
                         const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                         audioEngine.glideVoice(latchedVoiceId, finalRatio, settingsRef.current.baseFrequency);
                     });
                 }
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         // Auto-Latch Logic
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);

            // Fuzzy target finding for snapping
            let targetNode = getClosestNode(e.clientX, e.clientY);
            // Fallback to strict hoverNodeId if getClosestNode failed but hoverNodeId was somehow valid (rare, but good safety)
            if (!targetNode && cursor.hoverNodeId) {
                 targetNode = nodeMapRef.current.get(cursor.hoverNodeId) || phantomNodesRef.current.get(cursor.hoverNodeId) || null;
            }

            const shiftingGroup = shiftingNodeIdsRef.current;

            if (anchorNode && targetNode) {
                // If dragging to same node, do nothing (Tap-Shift already handled on Down)
                if (anchorNode.id !== targetNode.id) {
                    const allLatches = getAllLatchesAsMap();
                    const newLatches = executeShift(anchorNode, targetNode, allLatches);
                    if (newLatches) {
                        setPersistentLatches(newLatches);
                        if (onClearActiveChords) onClearActiveChords();
                    }
                }
            } else if (!targetNode) {
                // DROP TO DELETE (Stop Sound)
                const newLatches = new Map<string, Map<number, number>>(persistentLatchesRef.current);
                shiftingGroup.forEach(sourceId => {
                    newLatches.delete(sourceId);
                });
                setPersistentLatches(newLatches);
            }

            // Cleanup Shift State
            setShiftingNodeIds(new Set());
            shiftingNodeIdsRef.current = new Set();
        } 
        // --- NORMAL LOGIC ---
        else {
            // Pending Unlatch Logic: If user intended to unlatch but didn't drag/bend, do it now.
            if (cursor.pendingUnlatch && cursor.originNodeId) {
                if (cursor.hoverNodeId === cursor.originNodeId) {
                    // Stayed inside node -> Unlatch (Stop)
                    setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nModes = next.get(cursor.originNodeId!) || new Map<number, number>();
                         nModes.delete(latchMode);
                         if (nModes.size > 0) next.set(cursor.originNodeId!, nModes);
                         else next.delete(cursor.originNodeId!);
                         return next;
                     });
                } else {
                    // Dragged outside (Bent) -> Keep latched, reset pitch
                    // NOTE: The voice stays active in persistentLatches, but we snap pitch back to base.
                    const node = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
                    if (node) {
                        const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                        if (latchedModes) {
                             latchedModes.forEach((_, mode) => {
                                 const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                                 audioEngine.glideVoice(latchedVoiceId, node.ratio, settingsRef.current.baseFrequency);
                             });
                        }
                    }
                }
            }
            else if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

                // SUSTAIN-ON-RELEASE LOGIC (Standard, not already latched)
                if (isSustainActive && cursor.hoverNodeId) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(cursor.hoverNodeId!) || new Map<number, number>();
                         // Add the current instrument mode to the destination node
                         nodeModes.set(latchMode === 0 ? 2 : latchMode, Date.now());
                         next.set(cursor.hoverNodeId!, nodeModes);
                         return next;
                     });
                }

                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current,
              shiftGhostNodes: shiftGhostNodesRef.current // Pass map of ghosts
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; // New flag for conditional unlatching
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Track transferred voices to avoid re-triggering envelopes on React state update
  const transferredVoicesRef = useRef<Set<string>>(new Set());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Sync Shifting IDs ref
  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; }, [shiftingNodeIds]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Shift Ghosts
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Map<string, LatticeNode>();
      if (!settings.isShiftModeActive) return ghosts;

      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode) {
              const transpositionRatio = targetNode.ratio / anchorNode.ratio;
              const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

              shiftingNodeIds.forEach((sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
                      const newCoords: number[] = [];
                      for(let i=0; i<maxLength; i++) {
                          const val = (sourceNode.coords[i] || 0) + (diffCoords[i] || 0);
                          newCoords.push(val);
                      }

                      // Calculate Correct Octave via Pitch Ratio
                      // Reconstruct at Octave 0 to get normalized base
                      const tempId = `${newCoords.join(',')}:0`;
                      const tempNode = reconstructNode(tempId, settings);

                      if (tempNode) {
                          const normalizedBaseRatio = tempNode.ratio;
                          const idealRatio = sourceNode.ratio * transpositionRatio;
                          // Find necessary octave shift to match pitch
                          const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));

                          const newId = `${newCoords.join(',')}:${neededOctave}`;

                          const existing = nodeMap.get(newId);
                          if (existing) {
                              ghosts.set(newId, existing);
                          } else {
                              const ghost = reconstructNode(newId, settings);
                              if (ghost) ghosts.set(newId, ghost);
                          }
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, shiftingNodeIds, nodeMap, phantomNodes, settings]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); 
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   // Check if this ID was manually transferred (shifted) to prevent re-strike
                   if (transferredVoicesRef.current.has(voiceId)) {
                       transferredVoicesRef.current.delete(voiceId);
                       // Do nothing, the voice is already active and running
                   } else {
                       const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                       if (node) {
                           audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                           if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                       }
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper to extract full latch map including active chords
  const getAllLatchesAsMap = () => {
      const map = new Map<string, Map<number, number>>();
      audioLatchedNodesRef.current.forEach((activations, nodeId) => {
          const modeMap = new Map<number, number>();
          activations.forEach(a => {
              if (typeof a.mode === 'number') {
                  modeMap.set(a.mode, a.timestamp);
              }
          });
          if (modeMap.size > 0) map.set(nodeId, modeMap);
      });
      return map;
  };

  // Fuzzy Hit Search for Shift Snap
  const getClosestNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const maxDist = spacing * 0.6; // Generous snap radius
      const maxDistSq = maxDist * maxDist;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      let closest: LatticeNode | null = null;
      let closestDistSq = Infinity;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx;
                  const dy = y - ny;
                  const dSq = dx*dx + dy*dy;
                  if (dSq < closestDistSq && dSq < maxDistSq) {
                      closestDistSq = dSq;
                      closest = node;
                  }
              }
          }
      }

      // Check Phantom Nodes (Active nodes not currently in lattice)
      phantomNodesRef.current.forEach(node => {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          const dSq = dx*dx + dy*dy;
          if (dSq < closestDistSq && dSq < maxDistSq) {
              closestDistSq = dSq;
              closest = node;
          }
      });

      return closest;
  };

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }

      // Check Phantom Nodes
      for (const node of phantomNodesRef.current.values()) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;

          const isLatched = latchedMap.has(node.id);
          const activeZoom = isLatched ? zoomScale : 1.0;
          const activeRadius = baseRadius * activeZoom;

          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
      }

      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const triggerModulation = (node: LatticeNode) => {
        const newOrigin: GenerationOrigin = {
            coords: node.coords,
            octave: node.octave
        };

        const newPath = [...settingsRef.current.modulationPath, newOrigin];

        updateSettings({ 
            modulationPath: newPath,
            isModulationModeActive: false 
        });
  };

  // Helper to execute Shift
  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        // Only if Shift is NOT active. If Shift IS active, we handle modulation as a side effect of the shift.
        if (settings.isModulationModeActive && !settings.isShiftModeActive) {
            triggerModulation(hitNode);
            return; 
        }

        // --- SHIFT LOGIC (Initiate / Instant Shift) ---
        const isShiftMode = settings.isShiftModeActive;
        const allLatches = getAllLatchesAsMap(); // Get both manual latches and active chords
        const isClickedLatched = allLatches.has(hitNode.id);

        if (isShiftMode) {
             let anchorNode = null;
             let effectiveShiftingGroup = new Set<string>();

             if (isClickedLatched) {
                 // Existing Logic: Dragging an existing anchor
                 anchorNode = hitNode;
                 effectiveShiftingGroup = new Set(allLatches.keys()); // Shift everything active
             } else {
                 // New Logic: Instant Shift to Clicked Node
                 // 1. Find Implicit Anchor (Closest to "center" or simple ratio)
                 const latchedIds = Array.from(allLatches.keys());
                 if (latchedIds.length > 0) {
                     const nodes = latchedIds.map(id => nodeMapRef.current.get(id) || phantomNodesRef.current.get(id)).filter(n => n) as LatticeNode[];
                     // Sort by complexity/distance from origin to find "root"
                     nodes.sort((a, b) => {
                         const distA = a.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(a.octave);
                         const distB = b.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(b.octave);
                         return distA - distB;
                     });
                     const implicitAnchor = nodes[0];

                     if (implicitAnchor) {
                         // 2. Perform Instant Shift
                         const newLatches = executeShift(implicitAnchor, hitNode, allLatches); 
                         if (newLatches) {
                             // Update State
                             setPersistentLatches(newLatches);
                             persistentLatchesRef.current = newLatches; // Sync ref for immediate interaction consistency

                             // Clear any active stored chord definitions since we've manually moved them
                             if (onClearActiveChords) onClearActiveChords();

                             // The clicked node is now the anchor of the new shape
                             anchorNode = hitNode; 
                             effectiveShiftingGroup = new Set(newLatches.keys());

                             // Side-effect: Modulate if armed
                             if (settings.isModulationModeActive) triggerModulation(hitNode);
                         }
                     }
                 }
             }

             if (anchorNode) {
                 setShiftingNodeIds(effectiveShiftingGroup);
                 shiftingNodeIdsRef.current = effectiveShiftingGroup;

                 const newCursor: ActiveCursor = {
                    pointerId: e.pointerId,
                    originNodeId: anchorNode.id, 
                    hoverNodeId: anchorNode.id,
                    hasMoved: false,
                    interactionLockedNodeId: null,
                    isShiftAnchor: true // Mark as anchor for potential dragging
                };

                const nextRef = new Map(activeCursorsRef.current);
                nextRef.set(e.pointerId, newCursor);
                activeCursorsRef.current = nextRef;

                setActiveCursors(prev => {
                    const next = new Map(prev);
                    next.set(e.pointerId, newCursor);
                    return next;
                });
                return;
             }
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        let pendingUnlatch = false;

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             const nodeModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = nodeModes && nodeModes.has(latchMode);

             // Conditional Unlatch: If bend is enabled and note is active, wait for potential drag
             if (isBendEnabled && isAlreadyLatched) {
                 pendingUnlatch = true;
             } else {
                 setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                     const next = new Map(prev);
                     const nModes = next.get(hitNode.id) || new Map<number, number>();

                     if (nModes.has(latchMode)) {
                         nModes.delete(latchMode);
                     } else {
                         nModes.set(latchMode, Date.now());
                     }

                     if (nModes.size > 0) next.set(hitNode.id, nModes);
                     else next.delete(hitNode.id);
                     return next;
                 });
             }
        }

        if (((isBendEnabled || !isSustainActive) && !isShiftMode) && !pendingUnlatch) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        } else if (pendingUnlatch) {
             // Register cursor for bend tracking but don't start new voice
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ONLY voices in the Shifting Group
             const shiftingGroup = shiftingNodeIdsRef.current;
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 if (!shiftingGroup.has(nodeId)) return; // Skip non-shifting nodes

                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             // Glide Cursor Voice (if active)
             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);

             // Glide Sustained/Latched Voice (if interacting with active node)
             if (cursor.pendingUnlatch || persistentLatchesRef.current.has(cursor.originNodeId!)) {
                 const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                 if (latchedModes) {
                     latchedModes.forEach((_, mode) => {
                         const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                         audioEngine.glideVoice(latchedVoiceId, finalRatio, settingsRef.current.baseFrequency);
                     });
                 }
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         // Auto-Latch Logic
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);

            // Fuzzy target finding for snapping
            let targetNode = getClosestNode(e.clientX, e.clientY);
            // Fallback to strict hoverNodeId if getClosestNode failed but hoverNodeId was somehow valid (rare, but good safety)
            if (!targetNode && cursor.hoverNodeId) {
                 targetNode = nodeMapRef.current.get(cursor.hoverNodeId) || phantomNodesRef.current.get(cursor.hoverNodeId) || null;
            }

            const shiftingGroup = shiftingNodeIdsRef.current;

            if (anchorNode && targetNode) {
                // If dragging to same node, do nothing (Tap-Shift already handled on Down)
                if (anchorNode.id !== targetNode.id) {
                    const allLatches = getAllLatchesAsMap();
                    const newLatches = executeShift(anchorNode, targetNode, allLatches);
                    if (newLatches) {
                        setPersistentLatches(newLatches);
                        if (onClearActiveChords) onClearActiveChords();
                        // Side-effect: Modulate if armed
                        if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                    }
                } else {
                    // Didn't move, but check for Modulation trigger
                    if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                }
            } else if (!targetNode) {
                // DROP TO DELETE (Stop Sound)
                const newLatches = new Map<string, Map<number, number>>(persistentLatchesRef.current);
                shiftingGroup.forEach(sourceId => {
                    newLatches.delete(sourceId);
                });
                setPersistentLatches(newLatches);
            }

            // Cleanup Shift State
            setShiftingNodeIds(new Set());
            shiftingNodeIdsRef.current = new Set();
        } 
        // --- NORMAL LOGIC ---
        else {
            // Pending Unlatch Logic: If user intended to unlatch but didn't drag/bend, do it now.
            if (cursor.pendingUnlatch && cursor.originNodeId) {
                if (cursor.hoverNodeId === cursor.originNodeId) {
                    // Stayed inside node -> Unlatch (Stop)
                    setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nModes = next.get(cursor.originNodeId!) || new Map<number, number>();
                         nModes.delete(latchMode);
                         if (nModes.size > 0) next.set(cursor.originNodeId!, nModes);
                         else next.delete(cursor.originNodeId!);
                         return next;
                     });
                } else {
                    // Dragged outside (Bent) -> Keep latched, reset pitch
                    // NOTE: The voice stays active in persistentLatches, but we snap pitch back to base.
                    const node = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
                    if (node) {
                        const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                        if (latchedModes) {
                             latchedModes.forEach((_, mode) => {
                                 const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                                 audioEngine.glideVoice(latchedVoiceId, node.ratio, settingsRef.current.baseFrequency);
                             });
                        }
                    }
                }
            }
            else if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

                // SUSTAIN-ON-RELEASE LOGIC (Standard, not already latched)
                if (isSustainActive && cursor.hoverNodeId) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(cursor.hoverNodeId!) || new Map<number, number>();
                         // Add the current instrument mode to the destination node
                         nodeModes.set(latchMode === 0 ? 2 : latchMode, Date.now());
                         next.set(cursor.hoverNodeId!, nodeModes);
                         return next;
                     });
                }

                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const triggerModulation = (node: LatticeNode) => {
        const newOrigin: GenerationOrigin = {
            coords: node.coords,
            octave: node.octave
        };

        const newPath = [...settingsRef.current.modulationPath, newOrigin];

        updateSettings({ 
            modulationPath: newPath,
            isModulationModeActive: false 
        });
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        // Only if Shift is NOT active. If Shift IS active, we handle modulation as a side effect of the shift.
        if (settings.isModulationModeActive && !settings.isShiftModeActive) {
            triggerModulation(hitNode);
            return; 
        }

        // --- SHIFT LOGIC (Initiate / Instant Shift) ---
        const isShiftMode = settings.isShiftModeActive;
        const allLatches = getAllLatchesAsMap(); // Get both manual latches and active chords
        const isClickedLatched = allLatches.has(hitNode.id);

        if (isShiftMode) {
             let anchorNode = null;
             let effectiveShiftingGroup = new Set<string>();

             if (isClickedLatched) {
                 // Existing Logic: Dragging an existing anchor
                 anchorNode = hitNode;
                 effectiveShiftingGroup = new Set(allLatches.keys()); // Shift everything active
             } else {
                 // New Logic: Instant Shift to Clicked Node
                 // 1. Find Implicit Anchor (Closest to "center" or simple ratio)
                 const latchedIds = Array.from(allLatches.keys());
                 if (latchedIds.length > 0) {
                     const nodes = latchedIds.map(id => nodeMapRef.current.get(id) || phantomNodesRef.current.get(id)).filter(n => n) as LatticeNode[];
                     // Sort by complexity/distance from origin to find "root"
                     nodes.sort((a, b) => {
                         const distA = a.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(a.octave);
                         const distB = b.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(b.octave);
                         return distA - distB;
                     });
                     const implicitAnchor = nodes[0];

                     if (implicitAnchor) {
                         // 2. Perform Instant Shift
                         const newLatches = executeShift(implicitAnchor, hitNode, allLatches); 
                         if (newLatches) {
                             // Update State
                             setPersistentLatches(newLatches);
                             persistentLatchesRef.current = newLatches; // Sync ref for immediate interaction consistency

                             // Clear any active stored chord definitions since we've manually moved them
                             if (onClearActiveChords) onClearActiveChords();

                             // The clicked node is now the anchor of the new shape
                             anchorNode = hitNode; 
                             effectiveShiftingGroup = new Set(newLatches.keys());

                             // Side-effect: Modulate if armed
                             if (settings.isModulationModeActive) triggerModulation(hitNode);
                         }
                     }
                 }
             }

             if (anchorNode) {
                 setShiftingNodeIds(effectiveShiftingGroup);
                 shiftingNodeIdsRef.current = effectiveShiftingGroup;

                 const newCursor: ActiveCursor = {
                    pointerId: e.pointerId,
                    originNodeId: anchorNode.id, 
                    hoverNodeId: anchorNode.id,
                    hasMoved: false,
                    interactionLockedNodeId: null,
                    isShiftAnchor: true // Mark as anchor for potential dragging
                };

                const nextRef = new Map(activeCursorsRef.current);
                nextRef.set(e.pointerId, newCursor);
                activeCursorsRef.current = nextRef;

                setActiveCursors(prev => {
                    const next = new Map(prev);
                    next.set(e.pointerId, newCursor);
                    return next;
                });
                return;
             }
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        let pendingUnlatch = false;

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             const nodeModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = nodeModes && nodeModes.has(latchMode);

             // Conditional Unlatch: If bend is enabled and note is active, wait for potential drag
             if (isBendEnabled && isAlreadyLatched) {
                 pendingUnlatch = true;
             } else {
                 setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                     const next = new Map(prev);
                     const nModes = next.get(hitNode.id) || new Map<number, number>();

                     if (nModes.has(latchMode)) {
                         nModes.delete(latchMode);
                     } else {
                         nModes.set(latchMode, Date.now());
                     }

                     if (nModes.size > 0) next.set(hitNode.id, nModes);
                     else next.delete(hitNode.id);
                     return next;
                 });
             }
        }

        if (((isBendEnabled || !isSustainActive) && !isShiftMode) && !pendingUnlatch) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        } else if (pendingUnlatch) {
             // Register cursor for bend tracking but don't start new voice
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ONLY voices in the Shifting Group
             const shiftingGroup = shiftingNodeIdsRef.current;
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 if (!shiftingGroup.has(nodeId)) return; // Skip non-shifting nodes

                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             // Glide Cursor Voice (if active)
             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);

             // Glide Sustained/Latched Voice (if interacting with active node)
             if (cursor.pendingUnlatch || persistentLatchesRef.current.has(cursor.originNodeId!)) {
                 const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                 if (latchedModes) {
                     latchedModes.forEach((_, mode) => {
                         const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                         audioEngine.glideVoice(latchedVoiceId, finalRatio, settingsRef.current.baseFrequency);
                     });
                 }
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         // Auto-Latch Logic
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);

            // Fuzzy target finding for snapping
            let targetNode = getClosestNode(e.clientX, e.clientY);
            // Fallback to strict hoverNodeId if getClosestNode failed but hoverNodeId was somehow valid (rare, but good safety)
            if (!targetNode && cursor.hoverNodeId) {
                 targetNode = nodeMapRef.current.get(cursor.hoverNodeId) || phantomNodesRef.current.get(cursor.hoverNodeId) || null;
            }

            const shiftingGroup = shiftingNodeIdsRef.current;

            if (anchorNode && targetNode) {
                // If dragging to same node, do nothing (Tap-Shift already handled on Down)
                if (anchorNode.id !== targetNode.id) {
                    const allLatches = getAllLatchesAsMap();
                    const newLatches = executeShift(anchorNode, targetNode, allLatches);
                    if (newLatches) {
                        setPersistentLatches(newLatches);
                        if (onClearActiveChords) onClearActiveChords();
                        // Side-effect: Modulate if armed
                        if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                    }
                } else {
                    // Didn't move, but check for Modulation trigger
                    if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                }
            } else if (!targetNode) {
                // DROP TO DELETE (Stop Sound)
                const newLatches = new Map<string, Map<number, number>>(persistentLatchesRef.current);
                shiftingGroup.forEach(sourceId => {
                    newLatches.delete(sourceId);
                });
                setPersistentLatches(newLatches);
            }

            // Cleanup Shift State
            setShiftingNodeIds(new Set());
            shiftingNodeIdsRef.current = new Set();
        } 
        // --- NORMAL LOGIC ---
        else {
            // Pending Unlatch Logic: If user intended to unlatch but didn't drag/bend, do it now.
            if (cursor.pendingUnlatch && cursor.originNodeId) {
                if (cursor.hoverNodeId === cursor.originNodeId) {
                    // Stayed inside node -> Unlatch (Stop)
                    setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nModes = next.get(cursor.originNodeId!) || new Map<number, number>();
                         nModes.delete(latchMode);
                         if (nModes.size > 0) next.set(cursor.originNodeId!, nModes);
                         else next.delete(cursor.originNodeId!);
                         return next;
                     });
                } else {
                    // Dragged outside (Bent) -> Keep latched, reset pitch
                    // NOTE: The voice stays active in persistentLatches, but we snap pitch back to base.
                    const node = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
                    if (node) {
                        const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                        if (latchedModes) {
                             latchedModes.forEach((_, mode) => {
                                 const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                                 audioEngine.glideVoice(latchedVoiceId, node.ratio, settingsRef.current.baseFrequency);
                             });
                        }
                    }
                }
            }
            else if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

                // SUSTAIN-ON-RELEASE LOGIC (Standard, not already latched)
                if (isSustainActive && cursor.hoverNodeId) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(cursor.hoverNodeId!) || new Map<number, number>();
                         // Add the current instrument mode to the destination node
                         nodeModes.set(latchMode === 0 ? 2 : latchMode, Date.now());
                         next.set(cursor.hoverNodeId!, nodeModes);
                         return next;
                     });
                }

                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current,
              shiftGhostNodes: shiftGhostNodesRef.current // Pass map of ghosts
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; // New flag for conditional unlatching
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Track transferred voices to avoid re-triggering envelopes on React state update
  const transferredVoicesRef = useRef<Set<string>>(new Set());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Sync Shifting IDs ref
  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; }, [shiftingNodeIds]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Shift Ghosts
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Map<string, LatticeNode>();
      if (!settings.isShiftModeActive) return ghosts;

      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode) {
              const transpositionRatio = targetNode.ratio / anchorNode.ratio;
              const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

              shiftingNodeIds.forEach((sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
                      const newCoords: number[] = [];
                      for(let i=0; i<maxLength; i++) {
                          const val = (sourceNode.coords[i] || 0) + (diffCoords[i] || 0);
                          newCoords.push(val);
                      }

                      // Calculate Correct Octave via Pitch Ratio
                      // Reconstruct at Octave 0 to get normalized base
                      const tempId = `${newCoords.join(',')}:0`;
                      const tempNode = reconstructNode(tempId, settings);

                      if (tempNode) {
                          const normalizedBaseRatio = tempNode.ratio;
                          const idealRatio = sourceNode.ratio * transpositionRatio;
                          // Find necessary octave shift to match pitch
                          const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));

                          const newId = `${newCoords.join(',')}:${neededOctave}`;

                          const existing = nodeMap.get(newId);
                          if (existing) {
                              ghosts.set(newId, existing);
                          } else {
                              const ghost = reconstructNode(newId, settings);
                              if (ghost) ghosts.set(newId, ghost);
                          }
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, shiftingNodeIds, nodeMap, phantomNodes, settings]);

  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); 
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   // Check if this ID was manually transferred (shifted) to prevent re-strike
                   if (transferredVoicesRef.current.has(voiceId)) {
                       transferredVoicesRef.current.delete(voiceId);
                       // Do nothing, the voice is already active and running
                   } else {
                       const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                       if (node) {
                           audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                           if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                       }
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper to extract full latch map including active chords
  const getAllLatchesAsMap = () => {
      const map = new Map<string, Map<number, number>>();
      audioLatchedNodesRef.current.forEach((activations, nodeId) => {
          const modeMap = new Map<number, number>();
          activations.forEach(a => {
              if (typeof a.mode === 'number') {
                  modeMap.set(a.mode, a.timestamp);
              }
          });
          if (modeMap.size > 0) map.set(nodeId, modeMap);
      });
      return map;
  };

  // Fuzzy Hit Search for Shift Snap
  const getClosestNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const maxDist = spacing * 0.6; // Generous snap radius
      const maxDistSq = maxDist * maxDist;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      let closest: LatticeNode | null = null;
      let closestDistSq = Infinity;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx;
                  const dy = y - ny;
                  const dSq = dx*dx + dy*dy;
                  if (dSq < closestDistSq && dSq < maxDistSq) {
                      closestDistSq = dSq;
                      closest = node;
                  }
              }
          }
      }

      // Check Phantom Nodes (Active nodes not currently in lattice)
      phantomNodesRef.current.forEach(node => {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          const dSq = dx*dx + dy*dy;
          if (dSq < closestDistSq && dSq < maxDistSq) {
              closestDistSq = dSq;
              closest = node;
          }
      });

      return closest;
  };

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }

      // Check Phantom Nodes
      for (const node of phantomNodesRef.current.values()) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;

          const isLatched = latchedMap.has(node.id);
          const activeZoom = isLatched ? zoomScale : 1.0;
          const activeRadius = baseRadius * activeZoom;

          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
      }

      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const triggerModulation = (node: LatticeNode) => {
        const newOrigin: GenerationOrigin = {
            coords: node.coords,
            octave: node.octave
        };

        const newPath = [...settingsRef.current.modulationPath, newOrigin];

        updateSettings({ 
            modulationPath: newPath,
            isModulationModeActive: false 
        });
  };

  // Helper to execute Shift
  const executeShift = (anchorNode: LatticeNode, targetNode: LatticeNode, currentLatches: Map<string, Map<number, number>>) => {
      if (anchorNode.id === targetNode.id) return null;

      const transpositionRatio = targetNode.ratio / anchorNode.ratio;
      const diffCoords = targetNode.coords.map((c, i) => c - (anchorNode.coords[i] || 0));

      const newLatches = new Map<string, Map<number, number>>(currentLatches); // Copy full
      const nodesToMove = new Map<string, Map<number, number>>();

      // Identify sources to move (Currently assumed ALL latches for shifting)
      // If we support partial shifting in future, logic changes here.
      const shiftingGroup = shiftingNodeIdsRef.current.size > 0 ? shiftingNodeIdsRef.current : new Set(currentLatches.keys());

      shiftingGroup.forEach(sourceId => {
          const modes = newLatches.get(sourceId);
          if (modes) {
              nodesToMove.set(sourceId, modes);
              newLatches.delete(sourceId); // Remove old location
          }
      });

      // Apply Move
      nodesToMove.forEach((modes, sourceId) => {
          const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
          if (sourceNode) {
              const maxLength = Math.max(sourceNode.coords.length, diffCoords.length);
              const newCoords: number[] = [];
              for(let i=0; i<maxLength; i++) {
                  const s = sourceNode.coords[i] || 0;
                  const d = diffCoords[i] || 0;
                  newCoords.push(Math.round(s + d));
              }

              const tempId = `${newCoords.join(',')}:0`;
              const tempNode = reconstructNode(tempId, settingsRef.current);

              if (tempNode) {
                  const normalizedBaseRatio = tempNode.ratio;
                  const idealRatio = sourceNode.ratio * transpositionRatio;
                  const neededOctave = Math.round(Math.log2(idealRatio / normalizedBaseRatio));
                  const newId = `${newCoords.join(',')}:${neededOctave}`;
                  const newNode = reconstructNode(newId, settingsRef.current);

                  if (newNode) {
                      modes.forEach((ts, m) => {
                          const oldVoiceId = `node-${sourceId}-${m}`;
                          const newVoiceId = `node-${newId}-${m}`;
                          audioEngine.transferVoice(oldVoiceId, newVoiceId, newNode.ratio, settingsRef.current.baseFrequency);
                          transferredVoicesRef.current.add(newVoiceId);
                      });

                      const targetModes = newLatches.get(newId) || new Map<number, number>();
                      modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                      newLatches.set(newId, targetModes);
                  }
              }
          }
      });

      // Auto Expand Depth Logic
      if (settingsRef.current.shiftAutoExpandsDepth) {
          const activeOrigin = settingsRef.current.modulationPath[settingsRef.current.modulationPath.length - 1];
          const originCoords = activeOrigin.coords;
          const nextDepths = { ...settingsRef.current.limitDepths };
          let depthChanged = false;
          const GENERATORS = [3, 5, 7, 9, 11, 13, 15]; 

          newLatches.forEach((_, nodeId) => {
              const parts = nodeId.split(':');
              if (parts.length > 0) {
                  const coords = parts[0].split(',').map(Number);
                  GENERATORS.forEach((gen, idx) => {
                      const val = coords[idx] || 0;
                      const originVal = originCoords[idx] || 0;
                      const dist = Math.abs(val - originVal);
                      // @ts-ignore
                      if (dist > (nextDepths[gen] || 0)) {
                          // @ts-ignore
                          nextDepths[gen] = Math.min(12, dist); 
                          depthChanged = true;
                      }
                  });
              }
          });

          if (depthChanged) {
              updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: nextDepths }));
          }
      }

      return newLatches;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        // Only if Shift is NOT active. If Shift IS active, we handle modulation as a side effect of the shift.
        if (settings.isModulationModeActive && !settings.isShiftModeActive) {
            triggerModulation(hitNode);
            return; 
        }

        // --- SHIFT LOGIC (Initiate / Instant Shift) ---
        const isShiftMode = settings.isShiftModeActive;
        const allLatches = getAllLatchesAsMap(); // Get both manual latches and active chords
        const isClickedLatched = allLatches.has(hitNode.id);

        if (isShiftMode) {
             let anchorNode = null;
             let effectiveShiftingGroup = new Set<string>();

             if (isClickedLatched) {
                 // Existing Logic: Dragging an existing anchor
                 anchorNode = hitNode;
                 effectiveShiftingGroup = new Set(allLatches.keys()); // Shift everything active
             } else {
                 // New Logic: Instant Shift to Clicked Node
                 // 1. Find Implicit Anchor (Closest to "center" or simple ratio)
                 const latchedIds = Array.from(allLatches.keys());
                 if (latchedIds.length > 0) {
                     const nodes = latchedIds.map(id => nodeMapRef.current.get(id) || phantomNodesRef.current.get(id)).filter(n => n) as LatticeNode[];
                     // Sort by complexity/distance from origin to find "root"
                     nodes.sort((a, b) => {
                         const distA = a.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(a.octave);
                         const distB = b.coords.reduce((sum, v) => sum + Math.abs(v), 0) + Math.abs(b.octave);
                         return distA - distB;
                     });
                     const implicitAnchor = nodes[0];

                     if (implicitAnchor) {
                         // 2. Perform Instant Shift
                         const newLatches = executeShift(implicitAnchor, hitNode, allLatches); 
                         if (newLatches) {
                             // Update State
                             setPersistentLatches(newLatches);
                             persistentLatchesRef.current = newLatches; // Sync ref for immediate interaction consistency

                             // Clear any active stored chord definitions since we've manually moved them
                             if (onClearActiveChords) onClearActiveChords();

                             // The clicked node is now the anchor of the new shape
                             anchorNode = hitNode; 
                             effectiveShiftingGroup = new Set(newLatches.keys());

                             // Side-effect: Modulate if armed
                             if (settings.isModulationModeActive) triggerModulation(hitNode);
                         }
                     }
                 }
             }

             if (anchorNode) {
                 setShiftingNodeIds(effectiveShiftingGroup);
                 shiftingNodeIdsRef.current = effectiveShiftingGroup;

                 const newCursor: ActiveCursor = {
                    pointerId: e.pointerId,
                    originNodeId: anchorNode.id, 
                    hoverNodeId: anchorNode.id,
                    hasMoved: false,
                    interactionLockedNodeId: null,
                    isShiftAnchor: true // Mark as anchor for potential dragging
                };

                const nextRef = new Map(activeCursorsRef.current);
                nextRef.set(e.pointerId, newCursor);
                activeCursorsRef.current = nextRef;

                setActiveCursors(prev => {
                    const next = new Map(prev);
                    next.set(e.pointerId, newCursor);
                    return next;
                });
                return;
             }
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        let pendingUnlatch = false;

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             const nodeModes = persistentLatchesRef.current.get(hitNode.id);
             const isAlreadyLatched = nodeModes && nodeModes.has(latchMode);

             // Conditional Unlatch: If bend is enabled and note is active, wait for potential drag
             if (isBendEnabled && isAlreadyLatched) {
                 pendingUnlatch = true;
             } else {
                 setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                     const next = new Map(prev);
                     const nModes = next.get(hitNode.id) || new Map<number, number>();

                     if (nModes.has(latchMode)) {
                         nModes.delete(latchMode);
                     } else {
                         nModes.set(latchMode, Date.now());
                     }

                     if (nModes.size > 0) next.set(hitNode.id, nModes);
                     else next.delete(hitNode.id);
                     return next;
                 });
             }
        }

        if (((isBendEnabled || !isSustainActive) && !isShiftMode) && !pendingUnlatch) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        } else if (pendingUnlatch) {
             // Register cursor for bend tracking but don't start new voice
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false,
                pendingUnlatch: true
            };
            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ONLY voices in the Shifting Group
             const shiftingGroup = shiftingNodeIdsRef.current;
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 if (!shiftingGroup.has(nodeId)) return; // Skip non-shifting nodes

                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             // Glide Cursor Voice (if active)
             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);

             // Glide Sustained/Latched Voice (if interacting with active node)
             if (cursor.pendingUnlatch || persistentLatchesRef.current.has(cursor.originNodeId!)) {
                 const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                 if (latchedModes) {
                     latchedModes.forEach((_, mode) => {
                         const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                         audioEngine.glideVoice(latchedVoiceId, finalRatio, settingsRef.current.baseFrequency);
                     });
                 }
             }
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         // Auto-Latch Logic
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);

            // Fuzzy target finding for snapping
            let targetNode = getClosestNode(e.clientX, e.clientY);
            // Fallback to strict hoverNodeId if getClosestNode failed but hoverNodeId was somehow valid (rare, but good safety)
            if (!targetNode && cursor.hoverNodeId) {
                 targetNode = nodeMapRef.current.get(cursor.hoverNodeId) || phantomNodesRef.current.get(cursor.hoverNodeId) || null;
            }

            const shiftingGroup = shiftingNodeIdsRef.current;

            if (anchorNode && targetNode) {
                // If dragging to same node, do nothing (Tap-Shift already handled on Down)
                if (anchorNode.id !== targetNode.id) {
                    const allLatches = getAllLatchesAsMap();
                    const newLatches = executeShift(anchorNode, targetNode, allLatches);
                    if (newLatches) {
                        setPersistentLatches(newLatches);
                        if (onClearActiveChords) onClearActiveChords();
                        // Side-effect: Modulate if armed
                        if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                    }
                } else {
                    // Didn't move, but check for Modulation trigger
                    if (settingsRef.current.isModulationModeActive) triggerModulation(targetNode);
                }
            } else if (!targetNode) {
                // DROP TO DELETE (Stop Sound)
                const newLatches = new Map<string, Map<number, number>>(persistentLatchesRef.current);
                shiftingGroup.forEach(sourceId => {
                    newLatches.delete(sourceId);
                });
                setPersistentLatches(newLatches);
            }

            // Cleanup Shift State
            setShiftingNodeIds(new Set());
            shiftingNodeIdsRef.current = new Set();
        } 
        // --- NORMAL LOGIC ---
        else {
            // Pending Unlatch Logic: If user intended to unlatch but didn't drag/bend, do it now.
            if (cursor.pendingUnlatch && cursor.originNodeId) {
                if (cursor.hoverNodeId === cursor.originNodeId) {
                    // Stayed inside node -> Unlatch (Stop)
                    setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nModes = next.get(cursor.originNodeId!) || new Map<number, number>();
                         nModes.delete(latchMode);
                         if (nModes.size > 0) next.set(cursor.originNodeId!, nModes);
                         else next.delete(cursor.originNodeId!);
                         return next;
                     });
                } else {
                    // Dragged outside (Bent) -> Keep latched, reset pitch
                    // NOTE: The voice stays active in persistentLatches, but we snap pitch back to base.
                    const node = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
                    if (node) {
                        const latchedModes = persistentLatchesRef.current.get(cursor.originNodeId!);
                        if (latchedModes) {
                             latchedModes.forEach((_, mode) => {
                                 const latchedVoiceId = `node-${cursor.originNodeId}-${mode}`;
                                 audioEngine.glideVoice(latchedVoiceId, node.ratio, settingsRef.current.baseFrequency);
                             });
                        }
                    }
                }
            }
            else if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

                // SUSTAIN-ON-RELEASE LOGIC (Standard, not already latched)
                if (isSustainActive && cursor.hoverNodeId) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(cursor.hoverNodeId!) || new Map<number, number>();
                         // Add the current instrument mode to the destination node
                         nodeModes.set(latchMode === 0 ? 2 : latchMode, Date.now());
                         next.set(cursor.hoverNodeId!, nodeModes);
                         return next;
                     });
                }

                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current,
              shiftGhostNodes: shiftGhostNodesRef.current // Pass map of ghosts
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

