import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

export class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 11, 13];

// --- Reconstruction ---

export const reconstructNode = (id: string, settings: AppSettings): LatticeNode | null => {
    try {
        const parts = id.split(':');
        if (parts.length !== 2) return null;

        const coordStr = parts[0];
        const octStr = parts[1];
        const coords = coordStr.split(',').map(Number);
        const octave = parseInt(octStr);

        if (coords.some(isNaN) || isNaN(octave)) return null;

        let frac = new Fraction(1, 1);
        PRIMES.forEach((gen, idx) => {
            const val = coords[idx] || 0;
            // @ts-ignore
            const gRat = PRIME_RATIOS[gen];
            for(let i=0; i<Math.abs(val); i++) {
                frac = val > 0 ? frac.mul(gRat).normalize() : frac.mul(new Fraction(gRat.d, gRat.n)).normalize();
            }
        });
        frac = frac.shiftOctave(octave);

        const ratio = frac.n / frac.d;
        const { x, y } = projectCoordinates(coords, ratio, settings.latticeAspectRatio, settings.layoutApproach);

        return {
            id,
            coords,
            octave,
            ratio,
            n: frac.n,
            d: frac.d,
            label: `${frac.n}/${frac.d}`,
            x, y,
            limitTop: getMaxPrime(frac.n),
            limitBottom: getMaxPrime(frac.d),
            maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
            isGhost: true
        };
    } catch (e) {
        return null;
    }
};

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 
  const globalMaxDistance = settings.latticeMaxDistance ?? 12;

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p as 3|5|7|11|13];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  // 1. Check Per-Axis Depth Limit
                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  // 2. Check Global Manhattan Distance (Max Tonal Distance)
                  let totalDist = 0;
                  for (let k = 0; k < nextCoords.length; k++) {
                      totalDist += Math.abs(nextCoords[k] - origin.coords[k]);
                  }
                  if (totalDist > globalMaxDistance) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime as 3|5|7|11|13];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      visitedLocal.add(key);
                      localQueue.push({ coords: nextCoords, ratio: nextFrac });
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / (PRIME_RATIOS[prime as 3|5|7|11|13].n / PRIME_RATIOS[prime as 3|5|7|11|13].d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Find highest enabled odd limit
    let maxEnabledLimit = 1;
    settings.layerOrder.forEach(l => {
        if (!settings.hiddenLimits.includes(l) && ODD_IDENTITIES.includes(l)) {
            if (l > maxEnabledLimit) maxEnabledLimit = l;
        }
    });

    const activeIdentities = ODD_IDENTITIES.filter(id => id <= maxEnabledLimit);
    const N = activeIdentities.length;
    const centerOffset = (N - 1) / 2;

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout indices rotated 45 degrees
            // 1/1 at (0,0)
            // o increases: moves top-right
            // u increases: moves bottom-right
            const x = (o + u) - (N - 1);
            const y = (o - u);

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], // Not standard prime coords, but used for grid
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x * 1.0,
                y: y * 0.8, // Slightly squashed vertically
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { useState, useEffect, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice } from '../services/LatticeService';
import { GRID_CELL_SIZE } from '../constants';

export const useLatticeData = (settings: AppSettings, globalScale: number) => {
    const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
    const [isGenerating, setIsGenerating] = useState(false);
    const [dynamicSize, setDynamicSize] = useState(2000);

    const centerOffset = dynamicSize / 2;

    const nodeMap = useMemo(() => {
        return new Map(data.nodes.map(n => [n.id, n]));
    }, [data.nodes]);

    const spatialGrid = useMemo(() => {
        const grid = new Map<string, LatticeNode[]>();
        const spacing = settings.buttonSpacingScale * globalScale;

        data.nodes.forEach(node => {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            const col = Math.floor(x / GRID_CELL_SIZE);
            const row = Math.floor(y / GRID_CELL_SIZE);
            const key = `${col},${row}`;
            if (!grid.has(key)) grid.set(key, []);
            grid.get(key)!.push(node);
        });
        return grid;
    }, [data.nodes, settings.buttonSpacingScale, globalScale, centerOffset]);

    const adjacencyMap = useMemo(() => {
        const map = new Map<string, { target: string, limit: number }[]>();
        data.lines.forEach(line => {
            if (!map.has(line.sourceId)) map.set(line.sourceId, []);
            if (!map.has(line.targetId)) map.set(line.targetId, []);
            map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
            map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
        });
        return map;
    }, [data.lines]);

    const generationDeps = useMemo(() => {
        return JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            depths: settings.limitDepths,
            maxDist: settings.latticeMaxDistance, // Ensure distance change triggers regeneration
            hidden: settings.hiddenLimits,
            ratio: settings.latticeAspectRatio,
            skin: settings.activeSkin,
            path: settings.modulationPath
        });
    }, [
        settings.tuningSystem, 
        settings.layoutApproach, 
        settings.limitDepths, 
        settings.latticeMaxDistance, // Added dependency
        settings.hiddenLimits, 
        settings.latticeAspectRatio, 
        settings.activeSkin, 
        settings.modulationPath
    ]);

    useEffect(() => {
        setIsGenerating(true);
        const timerId = setTimeout(() => {
            // 1. Generate full lattice based on depths and history
            const rawResult = generateLattice(settings, settings.modulationPath);

            // 2. Strict Filtering based on hiddenLimits
            const hiddenSet = new Set(settings.hiddenLimits);

            // Filter Nodes: A node is visible if neither its Numerator nor Denominator limit is hidden
            const visibleNodes = rawResult.nodes.filter(n => {
                return !hiddenSet.has(n.maxPrime);
            });

            const visibleNodeIds = new Set(visibleNodes.map(n => n.id));

            // Filter Lines: Visible if limit is not hidden AND both endpoints are visible
            const visibleLines = rawResult.lines.filter(l => {
                if (hiddenSet.has(l.limit)) return false;
                if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
                return true;
            });

            setData({ nodes: visibleNodes, lines: visibleLines });
            setIsGenerating(false);
        }, 10);
        return () => clearTimeout(timerId);
    }, [generationDeps]);

    useEffect(() => {
        if (data.nodes.length === 0) return;

        let maxExtent = 0;
        for (const n of data.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const spacing = settings.buttonSpacingScale * globalScale;
        const padding = 1000; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.min(Math.max(calculatedSize, 2000), 12000);

        if (Math.abs(finalSize - dynamicSize) > 100) {
            setDynamicSize(finalSize);
        }
    }, [data.nodes, settings.buttonSpacingScale, globalScale]);

    return { data, isGenerating, dynamicSize, nodeMap, spatialGrid, adjacencyMap, centerOffset };
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Order corresponds to [3, 5, 7, 9, 11, 13, 15]
export const BASIS_VECTORS_X = [
    100,  // Generator 3
    30,   // Generator 5
    20,   // Generator 7
    200,  // Generator 9 (Approximately 2 * 3-vector)
    -20,  // Generator 11
    -55,  // Generator 13 (Increased negative offset for distinct spacing)
    130   // Generator 15 (Approximately 3-vector + 5-vector)
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 

    // Map coords to named primes for non-lattice layouts (legacy support for simple mappings)
    // Note: This mapping assumes the first 3 indices are 3, 5, 7. 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p9 = coords[3] || 0;
    const p11 = coords[4] || 0;
    const p13 = coords[5] || 0;
    const p15 = coords[6] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        // Handled in LatticeService for geometry, this is a fallback if called
        x = coords[0] * spacing;
        y = coords[1] * spacing;
    }
    else if (approach === 'row') {
        // Linear frequency mapping
        x = Math.log2(ratio) * 1200; 

        // Y-axis stacking based on complexity/limit
        // We find the highest active generator index
        let maxIndex = 0;
        for(let i = 0; i < coords.length; i++) {
            if (coords[i] !== 0) maxIndex = Math.max(maxIndex, i);
        }

        // Alternating up/down based on index parity for separation
        const dir = maxIndex % 2 === 0 ? 1 : -1;
        y = dir * (maxIndex * spacing * 0.6);

        // Add subtle offset for 3 and 5 to prevent overlap in center
        y += (p3 * 5 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.9;
        // Standard Hex: 3 and 5 axes
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        // Z-axis/depth offset for higher limits
        x += (p11 * 0.25 + p9 * 0.5) * hexUnit;
        y += (p13 * 0.25 + p15 * 0.5) * hexUnit;

        x = x * (1.0 / aspectRatio);
    }
    else if (approach === 'et_row' || approach === 'et_grid' || approach === 'et_wheel') {
        // ET Layouts generally ignore prime coords and rely purely on Ratio/Cents
        const semitones = Math.log2(ratio) * 12;

        if (approach === 'et_wheel') {
            const radius = spacing * 3;
            const angle = (semitones / 12) * Math.PI * 2 - (Math.PI / 2); // Start top
            x = Math.cos(angle) * radius;
            y = Math.sin(angle) * radius;
        } else if (approach === 'et_grid') {
            const col = Math.round(semitones);
            x = col * (spacing * 0.6);
            y = (semitones - col) * spacing * 10; // Detune on Y
        } else {
            // et_row
            x = semitones * (spacing * 0.8);
            y = 0;
        }
    }
    // Pythagorean Spiral & Row
    else if (approach === 'pyth_spiral') {
        // 3-limit stack wrapped
        const fifths = p3; // Only p3 is relevant effectively
        const radius = spacing * 2 + (fifths * 5);
        const angle = fifths * (Math.PI * 2 * (7/12)); // Circle of fifths angle
        x = Math.cos(angle) * radius;
        y = Math.sin(angle) * radius;
    }
    else if (approach === 'pyth_row') {
        x = p3 * spacing;
        y = p5 * spacing; // Just in case 5 is involved
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Order strictly corresponds to LatticeService PRIMES: [3, 5, 7, 11, 13]
export const BASIS_VECTORS_X = [
    100, // Prime 3: Major axis (Right)
    30,  // Prime 5: Minor axis (Right)
    20,  // Prime 7: Micro axis (Right)
    -35, // Prime 11: Offset Left (Distinct from 5/7 cluster)
    75   // Prime 13: Wide Right (Distinct lane between 5 and 3)
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        /**
         * Partch Tonality Diamond (Discrete Identity Space):
         * coords[0] = Otonality Index, coords[1] = Utonality Index
         */
        x = coords[0] * spacing;
        y = coords[1] * spacing;
        // Rotation handled in LatticeService for simpler line logic
    }
    else if (approach === 'row') {
        x = Math.log2(ratio) * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.6);
        y += (p3 * 5 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.9;
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;
        x += (p11 * 0.25) * hexUnit;
        y += (p13 * 0.25) * hexUnit;
        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

