const DSP_CLASSES = `
// --- 2. BASIC DSP CLASSES ---
class PolyBLEP {
  constructor(sampleRate) { this.sampleRate = sampleRate; }
  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) { t /= dt; return t + t - t - t * t - 1.0; }
    else if (t > 1.0 - dt) { t = (t - 1.0) / dt; return t * t + t + t + 1.0; }
    return 0.0;
  }
}

class SVF {
  constructor() { this.low = 0.0; this.band = 0.0; this.high = 0.0; this.notch = 0.0; }
  reset() { this.low = 0.0; this.band = 0.0; this.high = 0.0; this.notch = 0.0; }

  // Optimized for block processing: f is calculated outside the sample loop
  process(input, f, q, type, peakGain = 1.0) {
    if (!Number.isFinite(this.low) || !Number.isFinite(this.band)) this.reset();

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    let out = 0.0;
    switch((type|0)) {
        case 0: out = this.low; break;
        case 1: out = this.high; break;
        case 2: out = this.band; break;
        case 3: out = this.notch; break;
        case 4: out = this.low + this.high + (this.band * peakGain); break;
        case 5: out = (this.low * peakGain) + this.high + this.band; break;
        case 6: out = this.low + (this.high * peakGain) + this.band; break;
        default: out = this.low;
    }

    return out;
  }
}

class ResonatorBank {
    constructor() { this.f1 = new SVF(); this.f2 = new SVF(); this.f3 = new SVF(); }
    reset() { this.f1.reset(); this.f2.reset(); this.f3.reset(); }
    process(input, sweep, pitchHz, sampleRate) {
        const pos = Math.max(0, Math.min(1, sweep)) * 4.0;
        const idx = Math.floor(pos);
        const frac = pos - idx;
        const nextIdx = Math.min(idx + 1, 4);
        const p1 = RESONANCES[idx];
        const p2 = RESONANCES[nextIdx];
        const pitchScale = 1.0 + 0.15 * Math.log2(Math.max(50, pitchHz) / 200);
        const f1_freq = (p1.f1 + (p2.f1 - p1.f1) * frac) * pitchScale;
        const f2_freq = (p1.f2 + (p2.f2 - p1.f2) * frac) * pitchScale;
        const f3_freq = (p1.f3 + (p2.f3 - p1.f3) * frac) * pitchScale;

        // Coeffs for SVF
        const ff1 = 2.0 * Math.sin(Math.PI * Math.max(20, Math.min(f1_freq, sampleRate*0.45)) / sampleRate);
        const ff2 = 2.0 * Math.sin(Math.PI * Math.max(20, Math.min(f2_freq, sampleRate*0.45)) / sampleRate);
        const ff3 = 2.0 * Math.sin(Math.PI * Math.max(20, Math.min(f3_freq, sampleRate*0.45)) / sampleRate);
        const res = 4.0; 
        const q = 1.0 / (res + 0.5);

        const out1 = this.f1.process(input, ff1, q, 2); 
        const out2 = this.f2.process(input, ff2, q, 2);
        const out3 = this.f3.process(input, ff3, q, 2);
        return (out1 * p1.g1) + (out2 * p1.g2) + (out3 * p1.g3);
    }
}

class Envelope {
  constructor() { this.stage = 'idle'; this.value = 0.0; this.velocity = 0.0; }
  trigger(velocity = 1.0) { this.stage = 'attack'; this.velocity = velocity; }
  release() { if (this.stage !== 'idle') this.stage = 'release'; }
  reset() { this.stage = 'idle'; this.value = 0.0; }

  process(config, dt, mode) {
    const att = config.attack || 0.01;
    const dec = config.decay || 0.1;
    const sus = config.sustain !== undefined ? config.sustain : 1.0;
    const rel = config.release || 0.1;

    switch (this.stage) {
      case 'idle': this.value = 0.0; return 0.0;
      case 'attack':
        this.value += (1.0 / Math.max(0.001, att)) * dt;
        if (this.value >= 1.0) { this.value = 1.0; this.stage = 'decay'; }
        return this.value * this.velocity;
      case 'decay':
        this.value += (sus - this.value) * ( (1.0 / Math.max(0.001, dec)) * dt * 5.0 ); 
        if (Math.abs(this.value - sus) < 0.001) { this.value = sus; this.stage = 'sustain'; }
        return this.value * this.velocity;
      case 'sustain':
        if (mode === 'latch' && config.pedalDecay > 0) {
            this.value -= this.value * ((1.0 / config.pedalDecay) * dt * 5.0);
            if (this.value < 0.001) { this.value = 0.0; this.stage = 'idle'; }
        } else if (mode === 'gate' && config.holdDecay > 0) {
            this.value -= this.value * ((1.0 / config.holdDecay) * dt * 5.0);
            if (this.value < 0.001) { this.value = 0.0; this.stage = 'idle'; }
        } else { this.value = sus; }
        return this.value * this.velocity;
      case 'release':
        this.value -= ( (1.0 / Math.max(0.001, rel)) * dt * 5.0 );
        if (this.value < 0.001) { this.value = 0.0; this.stage = 'idle'; }
        return this.value * this.velocity;
      default: return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) { this.phase = 0.0; this.blep = new PolyBLEP(sampleRate); this.sampleRate = sampleRate; }
  reset() { this.phase = 0.0; }
  process(freq, type, dt) {
    if (freq <= 0 || freq > 22000) return 0.0;
    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;
    switch (type) {
      case 'sine':
        { const index = this.phase * WAVETABLE_SIZE; const i = index|0; const f = index - i; sample = SINE_TABLE[i] + f * (SINE_TABLE[i + 1] - SINE_TABLE[i]); } break;
      case 'glottal':
        { const index = this.phase * WAVETABLE_SIZE; const i = index|0; const f = index - i; sample = GLOTTAL_TABLE[i] + f * (GLOTTAL_TABLE[i + 1] - GLOTTAL_TABLE[i]); } break;
      case 'triangle':
        sample = 2.0 * (Math.abs(-1.0 + (2.0 * this.phase)) - 0.5); break;
      case 'sawtooth':
        sample = (2.0 * this.phase) - 1.0; sample -= this.blep.get(this.phase, dt * freq); break;
      case 'square':
        sample = this.phase < 0.5 ? 1.0 : -1.0; sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0; sample -= this.blep.get(phase2, dt * freq); break;
      case 'noise': sample = (Math.random() * 2.0) - 1.0; break;
    }
    return sample;
  }
}
`;

const VOICE_LOGIC = `
// --- 3. VOICE LOGIC ---
class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false; this.id = ''; this.type = 'normal'; this.mode = 'gate'; this.panPos = 0; 
    this.baseFreq = 440; this.targetFreq = 440; this.startTime = 0; this.releaseTime = 0; this.activeTime = 0.0;
    this.oscs = [new Oscillator(sampleRate), new Oscillator(sampleRate), new Oscillator(sampleRate)];
    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.resonator = new ResonatorBank();
    this.noiseFilter = new SVF();
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.lfoRandoms = [0.0, 0.0, 0.0];
  }

  updateSampleRate(newRate) {
      if (this.sampleRate === newRate) return;
      this.sampleRate = newRate;
      this.oscs.forEach(osc => { osc.sampleRate = newRate; osc.blep.sampleRate = newRate; });
  }

  trigger(id, freq, type, mode) {
    this.id = id; this.type = type || 'normal'; this.mode = mode || 'gate';
    this.baseFreq = freq; this.targetFreq = freq;
    this.active = true; this.startTime = currentTime; this.releaseTime = 0; this.activeTime = 0.0;
    this.envs.forEach(env => env.trigger());
    this.lfoPhases.fill(0.0);
    this.lfoRandoms[0] = (Math.random() * 2.0) - 1.0;
    this.lfoRandoms[1] = (Math.random() * 2.0) - 1.0;
    this.lfoRandoms[2] = (Math.random() * 2.0) - 1.0;
  }

  release() { this.releaseTime = currentTime; this.envs.forEach(env => env.release()); }
  hardStop() { this.active = false; this.envs.forEach(env => env.reset()); this.filters.forEach(f => f.reset()); this.resonator.reset(); this.noiseFilter.reset(); }
  getLevel() { return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value); }
  getFilterTypeId(type) { if (type === 'highpass') return 1; if (type === 'bandpass') return 2; if (type === 'notch') return 3; if (type === 'peak') return 4; if (type === 'lowshelf') return 5; if (type === 'highshelf') return 6; return 0; }

  renderBlock(preset, dt, bufL, bufR, len, panSpeed, panDepth, startPanPhase, globalBend) {
    if (!this.active) return;
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
        const glideParam = preset.portamento || 0;
        let coef = glideParam <= 0.01 ? 1.0 : (1.0 - Math.exp(- (len * dt) / (glideParam * 0.5)));
        this.baseFreq += diff * coef;
    } else { this.baseFreq = this.targetFreq; }

    const osc1 = preset.osc1 || DUMMY_OSC_CONFIG;
    const osc2 = preset.osc2 || DUMMY_OSC_CONFIG;
    const osc3 = preset.osc3 || DUMMY_OSC_CONFIG;
    const matrix = preset.modMatrix || [];
    const hasMatrix = matrix.length > 0;
    const isSerialMode = osc1.waveform === 'glottal';

    // Optimization: Precalculate SVF params for the block
    const preCalcSVF = (oscConfig) => {
        const cut = Math.max(20, Math.min(oscConfig.filterCutoff, this.sampleRate*0.45));
        return { 
            f: 2.0 * Math.sin(Math.PI * cut / this.sampleRate),
            q: 1.0 / (oscConfig.filterResonance + 0.5),
            type: this.getFilterTypeId(oscConfig.filterType)
        };
    };
    const svf1 = preCalcSVF(osc1);
    const svf2 = preCalcSVF(osc2);
    const svf3 = preCalcSVF(osc3);

    let panPhase = startPanPhase;
    this.activeTime += (len * dt);

    for (let s = 0; s < len; s++) {
        let anyEnvActive = false;
        const e1 = this.envs[0].process(osc1, dt, this.mode); if (this.envs[0].stage !== 'idle') anyEnvActive = true;
        const e2 = this.envs[1].process(osc2, dt, this.mode); if (this.envs[1].stage !== 'idle') anyEnvActive = true;
        const e3 = this.envs[2].process(osc3, dt, this.mode); if (this.envs[2].stage !== 'idle') anyEnvActive = true;

        if (!anyEnvActive && s === len - 1) { this.active = false; }

        let voiceMix = 0.0;
        if (osc1.enabled && e1 > 0.0001) {
            let freq = this.baseFreq * globalBend * Math.pow(2, (osc1.coarseDetune + osc1.fineDetune) / 1200.0);
            let sig = this.oscs[0].process(freq, osc1.waveform, dt);
            sig = this.filters[0].process(sig, svf1.f, svf1.q, svf1.type);
            if (isSerialMode) {
                sig = this.filters[1].process(sig, svf2.f, svf2.q, svf2.type, osc2.gain * 8.0); 
                sig = this.filters[2].process(sig, svf3.f, svf3.q, svf3.type, osc3.gain * 8.0); 
            }
            voiceMix += sig * osc1.gain * e1;
        }

        if (!isSerialMode) {
            if (osc2.enabled && e2 > 0.0001) {
                let freq = this.baseFreq * globalBend * Math.pow(2, (osc2.coarseDetune + osc2.fineDetune) / 1200.0);
                let sig = this.oscs[1].process(freq, osc2.waveform, dt);
                sig = this.filters[1].process(sig, svf2.f, svf2.q, svf2.type);
                voiceMix += sig * osc2.gain * e2;
            }
            if (osc3.enabled && e3 > 0.0001) {
                let freq = this.baseFreq * globalBend * Math.pow(2, (osc3.coarseDetune + osc3.fineDetune) / 1200.0);
                let sig = this.oscs[2].process(freq, osc3.waveform, dt);
                sig = this.filters[2].process(sig, svf3.f, svf3.q, svf3.type);
                voiceMix += sig * osc3.gain * e3;
            }
        }

        if (preset.resonatorMix > 0.01) {
            const resSig = this.resonator.process(voiceMix, preset.resonatorSweep, this.baseFreq, this.sampleRate);
            voiceMix = (voiceMix * (1.0 - preset.resonatorMix)) + (resSig * preset.resonatorMix * 1.5);
        }

        panPhase += dt * panSpeed;
        const p = Math.max(-1.0, Math.min(1.0, (this.panPos * preset.spread) + (Math.sin((panPhase % 1.0) * TWO_PI) * panDepth)));
        bufL[s] += voiceMix * 0.5 * (1.0 - p) * preset.gain;
        bufR[s] += voiceMix * 0.5 * (1.0 + p) * preset.gain;
    }
  }
}
`;

const PROCESSOR_LOGIC = `
// --- 4. PROCESSOR LOGIC ---
class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.isOversamplingEnabled = true; this.globalBendMultiplier = 1.0;
    this.voices = [];
    for(let i=0; i<64; i++) { const v = new Voice(sampleRate); v.panPos = Math.sin(i * 123.45); this.voices.push(v); }
    this.presets = { normal: DUMMY_PRESET_DATA, latch: DUMMY_PRESET_DATA, strum: DUMMY_PRESET_DATA, brass: DUMMY_PRESET_DATA, keys: DUMMY_PRESET_DATA };
    this.maxPolyphony = 32; this.strumDuration = 0.5;
    this.xm1L = 0; this.ym1L = 0; this.xm1R = 0; this.ym1R = 0;
    this.panPhase = 0; this.eventQueue = [];
    this.port.onmessage = (e) => {
      const msg = e.data;
      if (typeof msg.time === 'number' && msg.time > currentTime) { this.eventQueue.push(msg); this.eventQueue.sort((a, b) => a.time - b.time); return; }
      this.handleMessage(msg);
    };
  }

  handleMessage(msg) {
      if (msg.type === 'update_preset') { const { mode, data } = msg; if (mode) { this.presets[mode] = this.normalizePreset(data); } }
      else if (msg.type === 'config') { if (msg.polyphony) this.maxPolyphony = msg.polyphony; if (msg.strumDuration) this.strumDuration = msg.strumDuration; if (msg.enableOversampling !== undefined) this.isOversamplingEnabled = msg.enableOversampling; if (msg.globalBend !== undefined) this.globalBendMultiplier = msg.globalBend; }
      else if (msg.type === 'note_on') { this.triggerVoice(msg.id, msg.freq, msg.voiceType, msg.mode); }
      else if (msg.type === 'note_off') { this.releaseVoice(msg.id); }
      else if (msg.type === 'glide') { this.glideVoice(msg.id, msg.freq); }
      else if (msg.type === 'transfer') { this.transferVoice(msg.id, msg.newId, msg.freq); }
      else if (msg.type === 'stop_all') { this.voices.forEach(v => v.hardStop()); this.eventQueue = []; }
      else if (msg.type === 'stop_group') { const prefix = msg.prefix; if (prefix) { this.eventQueue = this.eventQueue.filter(e => !(e.id && e.id.startsWith(prefix))); this.voices.forEach(v => { if (v.active && v.id.startsWith(prefix)) v.release(); }); } }
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) }, osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) }, osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          gain: data.gain || 0.5, spread: data.spread || 0, stereoPanSpeed: data.stereoPanSpeed || 0, stereoPanDepth: data.stereoPanDepth || 0,
          resonatorMix: data.resonatorMix || 0, resonatorSweep: data.resonatorSweep || 0,
          portamento: data.portamento || 0
      };
  }

  triggerVoice(id, freq, type, mode) {
    let freeVoice = null; let activeCount = 0; let oldestReleased = null; let oldestReleaseTime = Infinity;
    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            if (v.id === id) { v.trigger(id, freq, type, mode); return; }
            activeCount++;
            if (v.releaseTime > 0 && v.releaseTime < oldestReleaseTime) { oldestReleaseTime = v.releaseTime; oldestReleased = v; }
        } else if (!freeVoice) freeVoice = v;
    }
    const victim = (activeCount < this.maxPolyphony) ? freeVoice : (oldestReleased || freeVoice || this.voices[0]);
    if (victim) { if (victim.active && victim.id !== id) this.port.postMessage({ type: 'voice_stolen', id: victim.id }); victim.trigger(id, freq, type, mode); }
  }

  releaseVoice(id) { for (let i = 0; i < this.voices.length; i++) { if (this.voices[i].active && this.voices[i].id === id) v.release(); } }
  glideVoice(id, freq) { for (let i = 0; i < this.voices.length; i++) { if (this.voices[i].active && this.voices[i].id === id) v.targetFreq = freq; } }
  transferVoice(oldId, newId, freq) { for (let i = 0; i < this.voices.length; i++) { if (this.voices[i].active && this.voices[i].id === oldId) { v.id = newId; v.targetFreq = freq; return; } } }

  process(inputs, outputs, parameters) {
    while (this.eventQueue.length > 0 && this.eventQueue[0].time <= currentTime) this.handleMessage(this.eventQueue.shift());
    const output = outputs[0]; const channelL = output[0]; const channelR = output[1]; if (!channelL) return true;
    const len = channelL.length;

    // Safety Budget for older devices: 2.0ms on 128 samples is roughly 70% CPU usage
    const startTime = globalThis.performance ? globalThis.performance.now() : 0;
    const MAX_BUDGET_MS = 2.0; 

    const OVERSAMPLE = this.isOversamplingEnabled ? 2 : 1;
    const workingRate = sampleRate * OVERSAMPLE; const workingLen = len * OVERSAMPLE; const dt = 1.0 / workingRate;

    if (!this.mixBufferL || this.mixBufferL.length !== workingLen) { this.mixBufferL = new Float32Array(workingLen); this.mixBufferR = new Float32Array(workingLen); }
    this.mixBufferL.fill(0); this.mixBufferR.fill(0);

    let voicesProcessed = 0;
    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            if (v.mode === 'trigger' && v.releaseTime === 0 && (currentTime - v.startTime >= this.strumDuration)) v.release();
            v.renderBlock(this.presets[v.type] || this.presets.normal, dt, this.mixBufferL, this.mixBufferR, workingLen, this.presets.normal.stereoPanSpeed, this.presets.normal.stereoPanDepth, this.panPhase, this.globalBendMultiplier);
            voicesProcessed++;
            if (startTime > 0 && voicesProcessed % 2 === 0 && (globalThis.performance.now() - startTime > MAX_BUDGET_MS)) break;
        }
    }
    this.panPhase += (workingLen * dt * this.presets.normal.stereoPanSpeed); while (this.panPhase > 1.0) this.panPhase -= 1.0;

    // Downsampling & Fast Saturation
    for (let s = 0; s < len; s++) {
        let sl = 0, sr = 0;
        if (OVERSAMPLE === 2) { 
            sl = (this.mixBufferL[s*2] + this.mixBufferL[s*2+1]) * 0.5;
            sr = (this.mixBufferR[s*2] + this.mixBufferR[s*2+1]) * 0.5;
        } else {
            sl = this.mixBufferL[s]; sr = this.mixBufferR[s];
        }
        // Fast Saturation + DC blocker
        const outL = fastSoftClip(sl * 0.8); const outR = fastSoftClip(sr * 0.8);
        const yL = outL - this.xm1L + 0.995 * this.ym1L; this.xm1L = outL; this.ym1L = yL;
        const yR = outR - this.xm1R + 0.995 * this.ym1R; this.xm1R = outR; this.ym1R = yR;
        channelL[s] = yL; if (channelR) channelR[s] = yR;
    }
    return true;
  }
}
registerProcessor('synth-processor', PrismaProcessor);
`;

export const AUDIO_PROCESSOR_CODE = DSP_CONSTANTS + DSP_CLASSES + VOICE_LOGIC + PROCESSOR_LOGIC;

import { SynthPreset, AppSettings, ReverbType, PresetState, PlayMode, PlaybackMode } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';
import { midiService } from './MidiService';

// --- Typed Messages for Worklet ---
interface WorkletMessageBase {
    type: string;
    time?: number; 
}

interface UpdatePresetMessage extends WorkletMessageBase {
    type: 'update_preset';
    mode: string;
    data: any; 
}

interface ConfigMessage extends WorkletMessageBase {
    type: 'config';
    polyphony?: number;
    strumDuration?: number;
    enableOversampling?: boolean;
    globalBend?: number;
    wavetableSize?: number;
    interpolationType?: 'linear' | 'cubic';
}

interface NoteOnMessage extends WorkletMessageBase {
    type: 'note_on';
    id: string;
    freq: number;
    voiceType: string;
    mode: PlaybackMode;
}

interface NoteOffMessage extends WorkletMessageBase {
    type: 'note_off';
    id: string;
}

interface GlideMessage extends WorkletMessageBase {
    type: 'glide';
    id: string;
    freq: number;
}

interface TransferMessage extends WorkletMessageBase {
    type: 'transfer';
    id: string;
    newId: string;
    freq: number;
}

interface StopAllMessage extends WorkletMessageBase {
    type: 'stop_all';
}

interface StopGroupMessage extends WorkletMessageBase {
    type: 'stop_group';
    prefix: string;
}

type AudioWorkletMessage = UpdatePresetMessage | ConfigMessage | NoteOnMessage | NoteOffMessage | GlideMessage | StopAllMessage | StopGroupMessage | TransferMessage;

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // VST Mode Flag
  private isRemoteEngine = false;

  // Message Queue for pre-init commands
  private messageQueue: AudioWorkletMessage[] = [];

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private masterFilter: BiquadFilterNode | null = null; 
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  // Final Output Stage
  private finalMasterGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private globalBrightness: number = 1.0; 

  // Cache active presets for FX updates
  private activePresets: PresetState;

  private voiceStealListeners: Set<(id: string) => void> = new Set();

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum),
        brass: this.ensurePresetSafety(rawPresets.brass),
        keys: this.ensurePresetSafety(rawPresets.keys),
        percussion: this.ensurePresetSafety(rawPresets.percussion)
    };

    // Auto-init to pre-load audio resources immediately
    this.init().catch(e => console.warn("Auto-init postponed", e));

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  public onVoiceSteal(callback: (id: string) => void) {
      this.voiceStealListeners.add(callback);
      return () => { this.voiceStealListeners.delete(callback); };
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;
     const validReverbTypes: ReverbType[] = ['room', 'hall', 'cathedral', 'plate', 'shimmer'];
     let rType: ReverbType = 'hall';
     if (p.reverbType && validReverbTypes.includes(p.reverbType)) {
         rType = p.reverbType as ReverbType;
     }
     const safe: SynthPreset = {
         ...DEFAULT_PRESET,
         ...p,
         osc1: { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) },
         osc2: { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) },
         osc3: { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) },
         modMatrix: p.modMatrix || [],
         reverbType: rType,
         aspirationGain: p.aspirationGain !== undefined ? p.aspirationGain : 0,
         aspirationCutoff: p.aspirationCutoff !== undefined ? p.aspirationCutoff : 4000
     };
     const defaults = REVERB_DEFAULTS[rType];
     if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;
     return safe;
  }

  // Unified Message Dispatcher
  private postMessage(msg: AudioWorkletMessage) {
      if (this.isRemoteEngine) return;
      if (this.workletNode) {
          this.workletNode.port.postMessage(msg);
      } else {
          this.messageQueue.push(msg);
          if (!this.initPromise && !this.ctx) this.init();
      }
  }

  public updateSettings(settings: AppSettings) {
      // Very High Latency forces Oversampling OFF to save CPU
      const isLegacyMode = settings.audioLatencyHint === 'very-high';

      this.postMessage({ 
          type: 'config', 
          polyphony: isLegacyMode ? Math.min(settings.polyphony, 12) : settings.polyphony,
          strumDuration: settings.strumDuration,
          enableOversampling: isLegacyMode ? false : settings.enableOversampling,
          wavetableSize: settings.wavetableSize,
          interpolationType: settings.interpolationType
      });
  }

  public updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum', 'brass', 'keys', 'percussion'];
      let recomputeReverb = false;

      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum),
          brass: this.ensurePresetSafety(newPresets.brass),
          keys: this.ensurePresetSafety(newPresets.keys),
          percussion: this.ensurePresetSafety(newPresets.percussion)
      };

      if (!this.isRemoteEngine) {
          if (recomputeReverb && this.ctx) {
              this.updateReverbBuffer();
          }
          this.updateFX();
      }

      modes.forEach(mode => {
          this.postMessage({ 
              type: 'update_preset', 
              mode: mode, 
              data: this.activePresets[mode] 
          });
      });
  }

  public registerPreset(id: string, preset: SynthPreset) {
      this.postMessage({
          type: 'update_preset', 
          mode: id,
          data: this.ensurePresetSafety(preset)
      });
  }

  public async resume() {
      if (this.isRemoteEngine) return;
      if (!this.ctx) await this.init(); 
      if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
          try { await this.ctx.resume(); } catch (e) {}
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (window.__PRISMA_WRAPPER__ === 'juce_webview' || window.__postMessageToHost) {
            this.isRemoteEngine = true;
            return;
        }

        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const settings = store.getSnapshot().settings;
            const rawLatencyHint = settings.audioLatencyHint || 'playback';

            // For 'very-high', we use a larger buffer hint
            const latencyHint = rawLatencyHint === 'very-high' ? 0.25 : rawLatencyHint;

            this.ctx = new AudioContextClass({ latencyHint });

            this.ctx.onstatechange = () => {
                if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
                    this.ctx.resume().catch(() => {}); 
                }
            };

            try {
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const url = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(url);
                URL.revokeObjectURL(url);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                this.workletNode.port.onmessage = (e) => {
                    if (e.data.type === 'voice_stolen') {
                        this.voiceStealListeners.forEach(cb => cb(e.data.id));
                    }
                };

                // Initialize State
                const isLegacy = rawLatencyHint === 'very-high';
                (['normal', 'latch', 'strum', 'brass', 'keys', 'percussion'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });

                this.workletNode!.port.postMessage({ 
                    type: 'config', 
                    polyphony: isLegacy ? Math.min(settings.polyphony, 12) : settings.polyphony,
                    strumDuration: settings.strumDuration,
                    enableOversampling: isLegacy ? false : settings.enableOversampling,
                    wavetableSize: settings.wavetableSize,
                    interpolationType: settings.interpolationType
                });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

                if (this.messageQueue.length > 0) {
                    this.messageQueue.forEach(msg => this.workletNode!.port.postMessage(msg));
                    this.messageQueue = [];
                }

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx || this.isRemoteEngine) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
        this.masterFilter?.disconnect();
        this.finalMasterGain?.disconnect();
    } catch(e) { /* ignore */ }

    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterFilter.type = 'lowpass';
    this.masterFilter.frequency.value = 20000;
    this.masterFilter.Q.value = 0.5;

    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;

    this.finalMasterGain = this.ctx.createGain();
    this.finalMasterGain.gain.value = this.currentMasterVol;

    this.masterFilter.connect(this.limiter);
    this.limiter.connect(this.finalMasterGain);
    this.finalMasterGain.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.masterFilter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.masterFilter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.masterFilter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx || this.isRemoteEngine) return;

      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': decay = 3.0; density = 0.8; break;
          case 'hall': decay = 2.0; density = 0.6; preDelay = 0.02; break;
          case 'cathedral': decay = 1.5; density = 0.4; preDelay = 0.04; break;
          case 'plate': decay = 4.0; density = 1.0; break;
          case 'shimmer': decay = 0.8; density = 0.2; break;
          default: decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx || this.isRemoteEngine) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.masterFilter) {
          const minFreq = 100;
          const maxFreq = 20000;
          const freq = minFreq * Math.pow(maxFreq/minFreq, this.globalBrightness);
          this.masterFilter.frequency.setTargetAtTime(freq, now, ramp);
      }

      if (this.finalMasterGain) {
          this.finalMasterGain.gain.setTargetAtTime(this.currentMasterVol, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      this.postMessage({ type: 'config', polyphony: count });
  }

  public setStrumDuration(duration: number) {
      this.postMessage({ type: 'config', strumDuration: duration });
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    if (!this.isRemoteEngine) this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      if (!this.isRemoteEngine) this.updateFX();
  }

  public setGlobalBrightness(val: number) {
      this.globalBrightness = val;
      if (!this.isRemoteEngine) this.updateFX();
  }

  public setGlobalBend(semitones: number) {
      const ratio = Math.pow(2, semitones / 12.0);
      this.postMessage({ type: 'config', globalBend: ratio });
  }

  public getContext(): AudioContext | null {
      return this.ctx;
  }

  public connectToRecordingDestination(destination: AudioNode) {
      if (this.finalMasterGain && !this.isRemoteEngine) {
          this.finalMasterGain.connect(destination);
      }
  }

  public startVoice(id: string, ratio: number, baseFrequency: number, presetSlot: string = 'normal', playbackMode: PlaybackMode = 'gate', time?: number) {
    this.resume();
    const freq = baseFrequency * ratio;
    this.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: presetSlot,
        mode: playbackMode,
        time: time
    });
  }

  public stopVoice(id: string, time?: number) {
    this.postMessage({ 
        type: 'note_off', 
        id: id,
        time: time
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    const freq = baseFrequency * newRatio;
    this.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public transferVoice(oldId: string, newId: string, ratio: number, baseFrequency: number) {
    const freq = baseFrequency * ratio;
    this.postMessage({
        type: 'transfer',
        id: oldId,
        newId: newId,
        freq: freq
    });
  }

  public stopAll() {
    this.postMessage({ type: 'stop_all' });
    if (this.ctx && !this.isRemoteEngine) this.setupFX();
  }

  public stopGroup(prefix: string) {
      this.postMessage({ type: 'stop_group', prefix: prefix });
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

import { useSyncExternalStore } from 'react';
import { AppSettings, SynthPreset, PresetState, PlayMode, StoreState } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_NORMAL_PRESET, DEFAULT_LATCH_PRESET, DEFAULT_STRUM_PRESET, DEFAULT_BRASS_PRESET, DEFAULT_KEYS_PRESET, DEFAULT_PERCUSSION_PRESET, DEFAULT_USER_BANK, DEFAULT_COLORS, REVERB_DEFAULTS } from '../constants';
import { XmlService } from './XmlService';

const SETTINGS_KEY = 'prismatonal_settings_v5'; 
const PRESET_KEY = 'prismatonal_presets_v5';
const USER_BANK_KEY = 'prismatonal_user_bank_v1';

class PrismaStore {
  private state: StoreState;
  private listeners: Set<() => void> = new Set();

  constructor() {
    // Hardware-aware Smart Default Polyphony & Quality
    const cores = navigator.hardwareConcurrency || 4;
    let safePolyphony = 8;
    let safeOversampling = false; 
    let defaultLatency: AppSettings['audioLatencyHint'] = 'playback';

    // If device is likely an older iPad (e.g. iPad 7th gen has 4 cores but legacy behavior)
    if (cores <= 4) {
        safePolyphony = 6;
        defaultLatency = 'very-high';
    }
    else if (cores >= 8) {
        safePolyphony = 12;
        defaultLatency = 'interactive';
    }

    // Load Settings with Robust Deep Merge
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    let loadedSettings: AppSettings = { 
        ...DEFAULT_SETTINGS, 
        polyphony: safePolyphony, 
        enableOversampling: safeOversampling,
        audioLatencyHint: defaultLatency
    };

    if (savedSettings) {
        try {
            const parsed = JSON.parse(savedSettings);
            loadedSettings = {
                ...DEFAULT_SETTINGS,
                ...parsed,
                // Ensure polyphony is not ridiculously high if loading old settings on a weak device
                polyphony: (parsed.polyphony && parsed.polyphony > 16 && cores <= 4) ? 8 : (parsed.polyphony || safePolyphony),
                enableOversampling: (parsed.enableOversampling !== undefined) ? parsed.enableOversampling : safeOversampling,
                audioLatencyHint: parsed.audioLatencyHint || defaultLatency,
                layoutApproach: parsed.layoutApproach || DEFAULT_SETTINGS.layoutApproach,
                limitDepths: { ...DEFAULT_SETTINGS.limitDepths, ...(parsed.limitDepths || {}) },
                colors: { ...DEFAULT_COLORS, ...(parsed.colors || {}) }, 
                uiPositions: { ...DEFAULT_SETTINGS.uiPositions, ...(parsed.uiPositions || {}) },
                arpeggios: parsed.arpeggios || DEFAULT_SETTINGS.arpeggios,
                arpBpm: parsed.arpBpm || DEFAULT_SETTINGS.arpBpm,
                wavetableSize: parsed.wavetableSize || DEFAULT_SETTINGS.wavetableSize,
                interpolationType: parsed.interpolationType || DEFAULT_SETTINGS.interpolationType
            };

            // Migrate stored chords to ensure soundConfig (if present) is valid
            if (loadedSettings.savedChords) {
                loadedSettings.savedChords = loadedSettings.savedChords.map(c => {
                    if (c.soundConfig) {
                        return { ...c, soundConfig: this.migratePreset(c.soundConfig) };
                    }
                    return c;
                });
            }

        } catch (e) {
            console.error("Failed to parse settings, reverting to defaults", e);
            loadedSettings = { ...DEFAULT_SETTINGS, polyphony: safePolyphony, enableOversampling: safeOversampling, audioLatencyHint: defaultLatency };
        }
    }

    // Load Presets
    const savedPresets = localStorage.getItem(PRESET_KEY);
    let loadedPresets: PresetState;

    if (savedPresets) {
        try {
            const parsed = JSON.parse(savedPresets);
            loadedPresets = {
                normal: this.migratePreset(parsed.normal || DEFAULT_NORMAL_PRESET),
                latch: this.migratePreset(parsed.latch || DEFAULT_LATCH_PRESET),
                strum: this.migratePreset(parsed.strum || DEFAULT_STRUM_PRESET),
                brass: this.migratePreset(parsed.brass || parsed.voice || DEFAULT_BRASS_PRESET),
                keys: this.migratePreset(parsed.keys || parsed.arpeggio || DEFAULT_KEYS_PRESET),
                percussion: this.migratePreset(parsed.percussion || DEFAULT_PERCUSSION_PRESET)
            };
        } catch (e) {
            loadedPresets = {
                normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                brass: JSON.parse(JSON.stringify(DEFAULT_BRASS_PRESET)),
                keys: JSON.parse(JSON.stringify(DEFAULT_KEYS_PRESET)),
                percussion: JSON.parse(JSON.stringify(DEFAULT_PERCUSSION_PRESET))
            };
        }
    } else {
        loadedPresets = {
            normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
            latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
            strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
            brass: JSON.parse(JSON.stringify(DEFAULT_BRASS_PRESET)),
            keys: JSON.parse(JSON.stringify(DEFAULT_KEYS_PRESET)),
            percussion: JSON.parse(JSON.stringify(DEFAULT_PERCUSSION_PRESET))
        };
    }

    // Load User Bank
    const savedUserBank = localStorage.getItem(USER_BANK_KEY);
    let loadedUserBank: SynthPreset[] = DEFAULT_USER_BANK;
    if (savedUserBank) {
        try {
            const parsed = JSON.parse(savedUserBank);
            if (Array.isArray(parsed)) {
                loadedUserBank = parsed.map(p => this.migratePreset(p));
            }
        } catch(e) {
            loadedUserBank = DEFAULT_USER_BANK;
        }
    }

    this.state = {
        settings: loadedSettings,
        presets: loadedPresets,
        userBank: loadedUserBank
    };
  }

  private migratePreset(p: any): SynthPreset {
      if (!p) return DEFAULT_NORMAL_PRESET;
      const safe: SynthPreset = {
          ...DEFAULT_NORMAL_PRESET, 
          ...p,
          osc1: { ...DEFAULT_NORMAL_PRESET.osc1, ...(p.osc1 || {}) },
          osc2: { ...DEFAULT_NORMAL_PRESET.osc2, ...(p.osc2 || {}) },
          osc3: { ...DEFAULT_NORMAL_PRESET.osc3, ...(p.osc3 || {}) },
          modMatrix: p.modMatrix || []
      };
      if (safe.reverbType && (safe.reverbSize === undefined || safe.reverbDamping === undefined || safe.reverbDiffusion === undefined)) {
          const defaults = REVERB_DEFAULTS[safe.reverbType] || REVERB_DEFAULTS['hall'];
          if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
          if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
          if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;
      }
      return safe;
  }

  updateSettings = (partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => {
    const current = this.state.settings;
    let next: AppSettings;
    if (typeof partial === 'function') { next = partial(current); } else { next = { ...current, ...partial }; }
    if (next === current) return;
    this.state = { ...this.state, settings: next };
    try {
        localStorage.setItem(SETTINGS_KEY, JSON.stringify(next));
    } catch (e: any) {
        if (e.name === 'QuotaExceededError' && next.backgroundImageData) {
            const safeSettings = { ...next, backgroundImageData: null };
            try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(safeSettings)); } catch (innerE) {}
        }
    }
    this.notify();
  };

  setPreset = (mode: PlayMode, newPreset: SynthPreset) => {
    const current = this.state.presets[mode];
    if (newPreset === current) return;
    const nextPresets = { ...this.state.presets, [mode]: newPreset };
    this.state = { ...this.state, presets: nextPresets };
    try { localStorage.setItem(PRESET_KEY, JSON.stringify(nextPresets)); } catch (e) {}
    this.notify();
  };

  saveUserPatch = (slotIndex: number, preset: SynthPreset) => {
      if (slotIndex < 0 || slotIndex >= 100) return;
      const newBank = [...this.state.userBank];
      newBank[slotIndex] = { ...preset, category: 'User' };
      this.state = { ...this.state, userBank: newBank };
      try { localStorage.setItem(USER_BANK_KEY, JSON.stringify(newBank)); } catch (e) {}
      this.notify();
  };

  exportXML = () => {
      const xml = XmlService.exportState(this.state);
      XmlService.downloadFile(xml);
  };

  importXML = async (file: File) => {
      try {
          const partial = await XmlService.parseImport(file);
          if (partial) {
              const nextState = { ...this.state, ...partial };
              if (nextState.presets) {
                  nextState.presets = {
                      normal: this.migratePreset(nextState.presets.normal),
                      latch: this.migratePreset(nextState.presets.latch),
                      strum: this.migratePreset(nextState.presets.strum),
                      brass: this.migratePreset(nextState.presets.brass || (nextState.presets as any).voice),
                      keys: this.migratePreset(nextState.presets.keys || (nextState.presets as any).arpeggio),
                      percussion: this.migratePreset(nextState.presets.percussion || DEFAULT_PERCUSSION_PRESET)
                  };
              }
              if (nextState.userBank) { nextState.userBank = nextState.userBank.map(p => this.migratePreset(p)); }
              if (nextState.settings && nextState.settings.savedChords) {
                  nextState.settings.savedChords = nextState.settings.savedChords.map(c => {
                      if (c.soundConfig) return { ...c, soundConfig: this.migratePreset(c.soundConfig) };
                      return c;
                  });
              }
              try {
                  localStorage.setItem(SETTINGS_KEY, JSON.stringify(nextState.settings));
                  localStorage.setItem(PRESET_KEY, JSON.stringify(nextState.presets));
                  localStorage.setItem(USER_BANK_KEY, JSON.stringify(nextState.userBank));
              } catch (e) {}
              this.state = nextState as StoreState;
              this.notify();
              return true;
          }
      } catch (e) { alert("Failed to import XML file."); }
      return false;
  };

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = () => { return this.state; };
  private notify() { this.listeners.forEach(l => l()); }
}

export const store = new PrismaStore();

export function useStore() {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);
  return {
    settings: state.settings,
    presets: state.presets, 
    userBank: state.userBank,
    updateSettings: store.updateSettings,
    setPreset: store.setPreset,
    saveUserPatch: store.saveUserPatch,
    exportXML: store.exportXML,
    importXML: store.importXML
  };
}

