  getFilterTypeId(type) { if (type === 'highpass') return 1; if (type === 'bandpass') return 2; if (type === 'notch') return 3; if (type === 'peak') return 4; if (type === 'lowshelf') return 5; if (type === 'highshelf') return 6; return 0; }

