  useEffect(() => {
      if (hasRunBenchmark.current) return;
      hasRunBenchmark.current = true;

      setTimeout(() => {
          const start = performance.now();
          const duration = 200; 
          let iterations = 0;

          const BLOCK_SIZE = 128;
          const NUM_VOICES = 32; 
          const buffer = new Float32Array(BLOCK_SIZE);

          const voices = Array.from({length: NUM_VOICES}, (_, i) => ({
              active: true,
              phase: Math.random(),
              inc: 0.01 + (i * 0.0001),
              gain: 0.5 - (i * 0.01)
          }));

          while (performance.now() - start < duration) {
              for(let k=0; k<BLOCK_SIZE; k++) buffer[k] = 0;
              for (let v = 0; v < NUM_VOICES; v++) {
                  const voice = voices[v];
                  let p = voice.phase;
                  const inc = voice.inc;
                  const g = voice.gain;
                  for (let i = 0; i < BLOCK_SIZE; i++) {
                      p += inc;
                      if (p >= 1.0) p -= 1.0;
                      buffer[i] += Math.sin(p * 6.28318) * g;
                  }
                  voice.phase = p;
              }
              iterations++;
