export const AUDIO_PROCESSOR_CODE = DSP_CONSTANTS + DSP_CLASSES + VOICE_LOGIC + PROCESSOR_LOGIC;

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Order strictly corresponds to LatticeService PRIMES: [3, 5, 7, 11, 13]
// Widened values to correct "vertical stretching" perception
export const BASIS_VECTORS_X = [
    120, // Prime 3: Major axis (Right)
    40,  // Prime 5: Minor axis (Right)
    30,  // Prime 7: Micro axis (Right)
    -50, // Prime 11: Offset Left (Distinct from 5/7 cluster)
    85   // Prime 13: Wide Right
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        x = coords[0] * spacing;
        y = coords[1] * spacing;
    }
    else if (approach === 'row') {
        x = Math.log2(ratio) * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.6);
        y += (p3 * 5 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.9;
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;
        x += (p11 * 0.25) * hexUnit;
        y += (p13 * 0.25) * hexUnit;
        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastBendUpdateRef = useRef<number>(0); 
  const lastVisualUpdateRef = useRef<number>(0); 

  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const visualsDirtyRef = useRef(true);
  const cachedVisualLatchedNodes = useRef<Map<string, NodeActivation[]>>(new Map());
  const cachedActiveLines = useRef<any[]>([]);
  const cachedBrightenedLines = useRef<any[]>([]);
  const cachedShiftGhostNodes = useRef<Map<string, LatticeNode>>(new Map());
  const cachedHarmonicNeighbors = useRef<Map<string, number>>(new Map());

  const [nodeGroups, setNodeGroups] = useState<Map<string, string>>(new Map());
  const activeGroupId = useRef<string>(`group-${Date.now()}`);

  useEffect(() => {
      if (!settings.isShiftModeActive) {
          activeGroupId.current = `group-${Date.now()}`;
      }
  }, [settings.isShiftModeActive]);

  const transferredVoicesRef = useRef<Set<string>>(new Set());
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; visualsDirtyRef.current = true; }, [shiftingNodeIds]);

  useEffect(() => { visualsDirtyRef.current = true; }, [
      persistentLatches, activeChordIds, externalTriggers, latchMode, isCurrentSustainEnabled, 
      settings.voiceLeadingSteps, settings.lineBrighteningEnabled, settings.isShiftModeActive, settings.limitVisuals
  ]);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev) => {
                  const next = new Map(prev);
                  if (next.has(nodeId)) next.delete(nodeId);
                  return next;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;
                    presetId = n.voiceMode;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, nodeMap, settings]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const centerOffsetRef = useRef(centerOffset);
  const nodeGroupsRef = useRef(nodeGroups);
  const phantomNodesRef = useRef(phantomNodes);
  const adjacencyMapRef = useRef(adjacencyMap);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useLayoutEffect(() => { nodeGroupsRef.current = nodeGroups; }, [nodeGroups]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { adjacencyMapRef.current = adjacencyMap; }, [adjacencyMap]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      updateRect();
      return () => window.removeEventListener('resize', updateRect);
  }, []);

  const updateVisualState = () => {
      const activeCursors = activeCursorsRef.current;
      const audioLatched = audioLatchedNodesRef.current;
      const nodeMap = nodeMapRef.current;
      const phantoms = phantomNodesRef.current;
      const mode = latchModeRef.current;
      const isSustainActive = isSustainEnabledRef.current;
      const lines = dataRef.current.lines;

      const visual = new Map<string, NodeActivation[]>();
      audioLatched.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              visual.get(nodeId)!.push({ mode: mode, timestamp: Date.now(), presetId: 'cursor' });
          }
      });

      cachedVisualLatchedNodes.current = visual;

      const activeLinesArr: any[] = [];
      if (visual.size >= 2) {
          for (const line of lines) {
              if (visual.has(line.sourceId) && visual.has(line.targetId)) activeLinesArr.push(line);
          }
      }
      cachedActiveLines.current = activeLinesArr;

      const brightenedLinesArr: any[] = [];
      if (settings.lineBrighteningEnabled && visual.size > 0) {
          lines.forEach(line => {
              if (visual.has(line.sourceId) || visual.has(line.targetId)) {
                  brightenedLinesArr.push(line);
              }
          });
      }
      cachedBrightenedLines.current = brightenedLinesArr;
  };

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        setPersistentLatches(prev => {
            if (mode === undefined) return new Map();
            const next = new Map(prev);
            for (const [nodeId, modeMap] of next.entries()) {
                if (modeMap.has(mode)) {
                    modeMap.delete(mode);
                    if (modeMap.size === 0) next.delete(nodeId);
                }
            }
            return next;
        });
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, nodeId) => {
            const n = nodeMap.get(nodeId);
            if (n) modeMap.forEach((_, mode) => result.push({ node: n, mode }));
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settingsRef.current.buttonSpacingScale * effectiveScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * effectiveScaleRef.current) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`
      ];

      const grid = spatialGridRef.current;
      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx; const dy = y - ny;
                  if (dx*dx + dy*dy < baseRadius*baseRadius) return node;
              }
          }
      }
      return null;
  };

  const renderLoop = (time: number) => {
      if (visualsDirtyRef.current) {
          updateVisualState();
          visualsDirtyRef.current = false;
      }
      if (bgLineCanvasRef.current && staticCanvasRef.current && dynamicCanvasRef.current && scrollContainerRef.current) {
          const view = {
              x: scrollContainerRef.current.scrollLeft, y: scrollContainerRef.current.scrollTop,
              w: scrollContainerRef.current.clientWidth, h: scrollContainerRef.current.clientHeight
          };
          rendererRef.current.render(
              bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current,
              {
                  data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: cachedVisualLatchedNodes.current,
                  activeLines: cachedActiveLines.current, brightenedLines: cachedBrightenedLines.current,
                  harmonicNeighbors: cachedHarmonicNeighbors.current, activeCursors: activeCursorsRef.current,
                  cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current,
                  globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current,
                  centerOffset: centerOffsetRef.current, view: view, time: time,
                  latchMode: latchModeRef.current, phantomNodes: phantomNodesRef.current,
                  shiftGhostNodes: cachedShiftGhostNodes.current
              }
          );
      }
      animationFrameRef.current = requestAnimationFrame(renderLoop);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(renderLoop);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode >= 1 && isCurrentSustainEnabled) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (!next.has(hitNode.id)) next.set(hitNode.id, new Map());
                  const modes = next.get(hitNode.id)!;
                  if (modes.has(latchMode)) modes.delete(latchMode);
                  else modes.set(latchMode, Date.now());
                  if (modes.size === 0) next.delete(hitNode.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 0 ? 'normal' : (['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'][latchMode] as PresetSlot));
          }
      }

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
      activeCursorsRef.current.set(e.pointerId, { 
          pointerId: e.pointerId, originNodeId: hitNode?.id || null, hoverNodeId: hitNode?.id || null, 
          hasMoved: false, interactionLockedNodeId: null 
      });
      visualsDirtyRef.current = true;
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (!cursor) return;
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode && cursor.hoverNodeId !== hitNode.id) {
          cursor.hoverNodeId = hitNode.id;
          if (latchMode === 0 || !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}`;
              audioEngine.stopVoice(voiceId);
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 0 ? 'normal' : (['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'][latchMode] as PresetSlot));
          }
      }
      visualsDirtyRef.current = true;
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursorsRef.current.has(e.pointerId)) {
          audioEngine.stopVoice(`cursor-${e.pointerId}`);
          activeCursorsRef.current.delete(e.pointerId);
          cursorPositionsRef.current.delete(e.pointerId);
          visualsDirtyRef.current = true;
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} 
         onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, minWidth: '100%', minHeight: '100%', backgroundColor: settings.solidColor || '#0f172a' }}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
  onClearActiveChords?: () => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; 
  pendingUnlatch?: boolean; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange, onClearActiveChords } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastBendUpdateRef = useRef<number>(0); 
  const lastVisualUpdateRef = useRef<number>(0); 

  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [shiftingNodeIds, setShiftingNodeIds] = useState<Set<string>>(new Set()); 
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const visualsDirtyRef = useRef(true);
  const cachedVisualLatchedNodes = useRef<Map<string, NodeActivation[]>>(new Map());
  const cachedActiveLines = useRef<any[]>([]);
  const cachedBrightenedLines = useRef<any[]>([]);
  const cachedShiftGhostNodes = useRef<Map<string, LatticeNode>>(new Map());
  const cachedHarmonicNeighbors = useRef<Map<string, number>>(new Map());

  const [nodeGroups, setNodeGroups] = useState<Map<string, string>>(new Map());
  const activeGroupId = useRef<string>(`group-${Date.now()}`);

  useEffect(() => {
      if (!settings.isShiftModeActive) {
          activeGroupId.current = `group-${Date.now()}`;
      }
  }, [settings.isShiftModeActive]);

  const transferredVoicesRef = useRef<Set<string>>(new Set());
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  const shiftingNodeIdsRef = useRef(shiftingNodeIds);
  useEffect(() => { shiftingNodeIdsRef.current = shiftingNodeIds; visualsDirtyRef.current = true; }, [shiftingNodeIds]);

  useEffect(() => { visualsDirtyRef.current = true; }, [
      persistentLatches, activeChordIds, externalTriggers, latchMode, isCurrentSustainEnabled, 
      settings.voiceLeadingSteps, settings.lineBrighteningEnabled, settings.isShiftModeActive, settings.limitVisuals
  ]);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev) => {
                  const next = new Map(prev);
                  if (next.has(nodeId)) next.delete(nodeId);
                  return next;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;
                    presetId = n.voiceMode;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, nodeMap, settings]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const centerOffsetRef = useRef(centerOffset);
  const nodeGroupsRef = useRef(nodeGroups);
  const phantomNodesRef = useRef(phantomNodes);
  const adjacencyMapRef = useRef(adjacencyMap);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);
  useLayoutEffect(() => { nodeGroupsRef.current = nodeGroups; }, [nodeGroups]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { adjacencyMapRef.current = adjacencyMap; }, [adjacencyMap]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      updateRect();
      return () => window.removeEventListener('resize', updateRect);
  }, []);

  const updateVisualState = () => {
      const activeCursors = activeCursorsRef.current;
      const audioLatched = audioLatchedNodesRef.current;
      const nodeMap = nodeMapRef.current;
      const phantoms = phantomNodesRef.current;
      const mode = latchModeRef.current;
      const isSustainActive = isSustainEnabledRef.current;
      const lines = dataRef.current.lines;

      const visual = new Map<string, NodeActivation[]>();
      audioLatched.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              visual.get(nodeId)!.push({ mode: mode, timestamp: Date.now(), presetId: 'cursor' });
          }
      });

      cachedVisualLatchedNodes.current = visual;

      const activeLinesArr: any[] = [];
      if (visual.size >= 2) {
          for (const line of lines) {
              if (visual.has(line.sourceId) && visual.has(line.targetId)) activeLinesArr.push(line);
          }
      }
      cachedActiveLines.current = activeLinesArr;

      const brightenedLinesArr: any[] = [];
      if (settings.lineBrighteningEnabled && visual.size > 0) {
          lines.forEach(line => {
              if (visual.has(line.sourceId) || visual.has(line.targetId)) {
                  brightenedLinesArr.push(line);
              }
          });
      }
      cachedBrightenedLines.current = brightenedLinesArr;
  };

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
            if (mode === undefined) return new Map<string, Map<number, number>>();
            const next = new Map<string, Map<number, number>>(prev);
            for (const [nodeId, modeMap] of next.entries()) {
                // Fix: modeMap is inferred as unknown in Map entries; cast to proper type
                const m = modeMap as Map<number, number>;
                if (m.has(mode)) {
                    // Clone inner map to avoid direct mutation of state references
                    const updatedInner = new Map(m);
                    updatedInner.delete(mode);
                    if (updatedInner.size === 0) next.delete(nodeId);
                    else next.set(nodeId, updatedInner);
                }
            }
            return next;
        });
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, nodeId) => {
            const n = nodeMap.get(nodeId);
            if (n) modeMap.forEach((_, mode) => result.push({ node: n, mode }));
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      // Fix: Use centerOffset from hook result as dynamicSizeRef.current is not defined
      const spacing = settingsRef.current.buttonSpacingScale * effectiveScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * effectiveScaleRef.current) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`
      ];

      const grid = spatialGridRef.current;
      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const dx = x - nx; const dy = y - ny;
                  if (dx*dx + dy*dy < baseRadius*baseRadius) return node;
              }
          }
      }
      return null;
  };

  const renderLoop = (time: number) => {
      if (visualsDirtyRef.current) {
          updateVisualState();
          visualsDirtyRef.current = false;
      }
      if (bgLineCanvasRef.current && staticCanvasRef.current && dynamicCanvasRef.current && scrollContainerRef.current) {
          const view = {
              x: scrollContainerRef.current.scrollLeft, y: scrollContainerRef.current.scrollTop,
              w: scrollContainerRef.current.clientWidth, h: scrollContainerRef.current.clientHeight
          };
          rendererRef.current.render(
              bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current,
              {
                  data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: cachedVisualLatchedNodes.current,
                  activeLines: cachedActiveLines.current, brightenedLines: cachedBrightenedLines.current,
                  harmonicNeighbors: cachedHarmonicNeighbors.current, activeCursors: activeCursorsRef.current,
                  cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current,
                  globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current,
                  centerOffset: centerOffsetRef.current, view: view, time: time,
                  latchMode: latchModeRef.current, phantomNodes: phantomNodesRef.current,
                  shiftGhostNodes: cachedShiftGhostNodes.current
              }
          );
      }
      animationFrameRef.current = requestAnimationFrame(renderLoop);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(renderLoop);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode >= 1 && isCurrentSustainEnabled) {
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  const next = new Map<string, Map<number, number>>(prev);
                  if (!next.has(hitNode.id)) next.set(hitNode.id, new Map<number, number>());

                  // Fix: retrieved inner map type is unknown; cast to proper Map type
                  const modes = next.get(hitNode.id) as Map<number, number>;
                  const updatedModes = new Map(modes);

                  if (updatedModes.has(latchMode)) updatedModes.delete(latchMode);
                  else updatedModes.set(latchMode, Date.now());

                  if (updatedModes.size === 0) next.delete(hitNode.id);
                  else next.set(hitNode.id, updatedModes);

                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 0 ? 'normal' : (['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'][latchMode] as PresetSlot));
          }
      }

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
      activeCursorsRef.current.set(e.pointerId, { 
          pointerId: e.pointerId, originNodeId: hitNode?.id || null, hoverNodeId: hitNode?.id || null, 
          hasMoved: false, interactionLockedNodeId: null 
      });
      visualsDirtyRef.current = true;
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (!cursor) return;
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode && cursor.hoverNodeId !== hitNode.id) {
          cursor.hoverNodeId = hitNode.id;
          if (latchMode === 0 || !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}`;
              audioEngine.stopVoice(voiceId);
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 0 ? 'normal' : (['latch', 'normal', 'strum', 'brass', 'keys', 'percussion'][latchMode] as PresetSlot));
          }
      }
      visualsDirtyRef.current = true;
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursorsRef.current.has(e.pointerId)) {
          audioEngine.stopVoice(`cursor-${e.pointerId}`);
          activeCursorsRef.current.delete(e.pointerId);
          cursorPositionsRef.current.delete(e.pointerId);
          visualsDirtyRef.current = true;
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} 
         onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, minWidth: '100%', minHeight: '100%', backgroundColor: settings.solidColor || '#0f172a' }}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

